/**
 * Where each game's files live on the guest — the single source of truth for the
 * customer Files tab's "Game files" control (components/customer/files/GameFilesBar.tsx).
 *
 * Plain, side-effect-free module: it is imported by a server page AND by the
 * "use client" file browser, so it must never import anything server-only.
 *
 * `gameFilesPath` is the folder a customer should LAND in to find the game's
 * server files, configs, mods/plugins folder and worlds/saves. It is a root-
 * absolute path in the file browser's virtual filesystem (which IS the guest's
 * real filesystem — the Files tab reads the guest as root over SFTP).
 *
 * HOW EACH ENTRY WAS DERIVED. Not guessed: from the `-v host:container` bind
 * mounts in each family's setupScript (prisma/catalog.ts, prisma/seed-wave*-games.ts;
 * later waves override earlier ones, e.g. unturned), the applier specs
 * (lib/game-applier-specs/*) and the mod installers (lib/mods/installers/*).
 * `source` records how far an entry has been checked:
 *   - "verified-live"     — `test -d` run against a real RUNNING customer guest
 *                           (2026-10-05, read-only, directory names only) for the
 *                           landing folder and every shortcut listed.
 *   - "from-setup-script" — derived from the code above; no running server of that
 *                           family was reachable/existing to confirm. The UI copes
 *                           either way: a missing folder falls back to the nearest
 *                           existing parent (nearestExistingParent below).
 * A "verified-live" entry with variant-specific shortcuts was verified on the
 * variant(s) named in `note`; the others stay derived from the installers.
 *
 * ADDING A GAME: add its family to GAME_FAMILIES (lib/games.ts) AND an entry here.
 * test/game-files-roots.test.ts fails the build of a family without one.
 *
 * Landing-folder rule: the host folder that holds what customers actually edit.
 * Where one bind mount holds everything, that mount. Where config and game install
 * are separate mounts (valheim, projectzomboid), the config side, with the install as
 * a shortcut. Where two sibling mounts are equally important and self-explanatory
 * (vrising, conan, sdtd...), their common parent, with each as a shortcut.
 */
import { GAME_DISPLAY, GAME_FAMILIES, type GameFamily } from "./games";

export type GameFilesShortcut = {
  label: string;
  path: string;
  /** Only offer this shortcut on these `Server.gameVariant` values (lower-case). Omit = every variant. */
  variants?: string[];
};

export type GameFilesRoot = {
  /** Landing folder, root-absolute, normalised, no "..". */
  gameFilesPath: string;
  /** Customer-facing game name, e.g. "Minecraft" (from GAME_DISPLAY). */
  label: string;
  extraShortcuts?: GameFilesShortcut[];
  source: "verified-live" | "from-setup-script";
  note?: string;
};

type Def = Omit<GameFilesRoot, "label">;

const live = (gameFilesPath: string, extraShortcuts?: GameFilesShortcut[], note?: string): Def => ({
  gameFilesPath, extraShortcuts, note, source: "verified-live",
});
const script = (gameFilesPath: string, extraShortcuts?: GameFilesShortcut[], note?: string): Def => ({
  gameFilesPath, extraShortcuts, note, source: "from-setup-script",
});
const sc = (label: string, path: string, variants?: string[]): GameFilesShortcut => ({ label, path, ...(variants ? { variants } : {}) });

const DEFS: Record<GameFamily, Def> = {
  minecraft: live("/opt/mc", [
    sc("Plugins", "/opt/mc/plugins", ["paper", "purpur"]),
    sc("Mods", "/opt/mc/mods", ["fabric", "forge"]),
    sc("World", "/opt/mc/world"),
    sc("Config", "/opt/mc/config"),
  ], "Verified on a live Paper server (/opt/mc, plugins, world, config, logs exist; mods does not on Paper). Fabric/Forge/Vanilla guests were unreachable; /opt/mc/mods is from the mod installer."),
  valheim: live("/opt/valheim/config", [
    sc("Worlds", "/opt/valheim/config/worlds_local"),
    sc("Mods (BepInEx)", "/opt/valheim/config/bepinex/plugins", ["bepinex"]),
    sc("Game install", "/opt/valheim/data"),
  ], "Config and game install are separate mounts (config:/config, data:/opt/valheim); config holds worlds, admin lists and mods. Verified on a live BepInEx and a live Vanilla server."),
  rust: script("/opt/rust", [
    sc("Oxide plugins", "/opt/rust/oxide/plugins", ["oxide"]),
    sc("Carbon plugins", "/opt/rust/carbon/plugins", ["carbon"]),
  ], "Mount is /opt/rust:/steamcmd/rust. GAME_CONTROL.dataRoots says /opt/rust/server: unconfirmed (no reachable live guest)."),
  palworld: live("/opt/palworld", [
    sc("Config", "/opt/palworld/Pal/Saved/Config/LinuxServer"),
    sc("Saves", "/opt/palworld/Pal/Saved/SaveGames"),
    sc("Backups", "/opt/palworld/backups"),
  ], "Single mount /opt/palworld:/palworld; the whole server install lives here."),
  cs2: script("/opt/cs2", [
    sc("Game content (csgo)", "/opt/cs2/game/csgo"),
    sc("Plugins (addons)", "/opt/cs2/game/csgo/addons", ["metamod"]),
  ], "Mount /opt/cs2:/home/steam/cs2-dedicated; csgo path from the CS2 mod installer."),
  terraria: script("/opt/terraria", [sc("Plugins", "/opt/terraria-plugins")],
    "Worlds and TShock config.json share /opt/terraria itself (mounted as /worlds and /tshock). GAME_CONTROL.dataRoots lists /opt/terraria/worlds, which the setup script never creates."),
  ark: script("/opt/ark", [
    sc("Saves", "/opt/ark/server/ShooterGame/Saved"),
    sc("Config", "/opt/ark/server/ShooterGame/Saved/Config/LinuxServer"),
  ], "Mount /opt/ark:/app; the image keeps the install in /app/server."),
  satisfactory: script("/opt/satisfactory", [sc("Saves", "/opt/satisfactory/saved")], "Mount /opt/satisfactory:/config."),
  projectzomboid: live("/opt/projectzomboid/config", [
    sc("Server settings", "/opt/projectzomboid/config/Server"),
    sc("Mods", "/opt/projectzomboid/config/mods"),
    sc("Saves", "/opt/projectzomboid/config/Saves/Multiplayer"),
    sc("Game install", "/opt/projectzomboid/server"),
  ], "Config (config:/project-zomboid-config) is separate from the install (server:/project-zomboid). Verified on a live b42 server."),
  sdtd: script("/opt/sdtd", [
    sc("Server files", "/opt/sdtd/serverfiles"),
    sc("Mods", "/opt/sdtd/serverfiles/Mods"),
    sc("Saves", "/opt/sdtd/saves"),
  ]),
  vrising: script("/opt/vrising", [
    sc("Server", "/opt/vrising/server"),
    sc("Settings and saves", "/opt/vrising/persistentdata"),
  ]),
  enshrouded: script("/opt/enshrouded", undefined, "Mount /opt/enshrouded:/opt/enshrouded. GAME_CONTROL.dataRoots lists /opt/enshrouded/server; unconfirmed."),
  factorio: script("/opt/factorio", [
    sc("Config", "/opt/factorio/config"),
    sc("Mods", "/opt/factorio/mods"),
    sc("Saves", "/opt/factorio/saves"),
  ]),
  gmod: script("/opt/gmod", [sc("Config", "/opt/gmod/garrysmod/cfg")], "Mount /opt/gmod:/serverdata/serverfiles."),
  conan: script("/opt/conan", [sc("Game", "/opt/conan/game"), sc("Config", "/opt/conan/config")]),
  unturned: script("/opt/unturned", undefined, "Mount /opt/unturned:/home/steam/Unturned/Servers (wave-7 script); each server instance is a folder here."),
  theforest: script("/opt/theforest", [sc("Config", "/opt/theforest/config")]),
  sonsoftheforest: script("/opt/sonsoftheforest", [sc("User data", "/opt/sonsoftheforest/userdata")]),
  bedrock: script("/opt/bedrock", [sc("Worlds", "/opt/bedrock/worlds")], "Mount /opt/bedrock:/data (itzg bedrock image)."),
  schedule1: script("/opt/schedule1", [sc("Saves", "/opt/schedule1/saves")], "Scaffold only: no dedicated server exists, so nothing is ever provisioned."),
  dragonwilds: script("/opt/dragonwilds", [sc("Saved", "/opt/dragonwilds/Saved")]),
  sunkenland: script("/opt/sunkenland", [sc("Worlds", "/opt/sunkenland/Worlds"), sc("Game", "/opt/sunkenland/game")]),
  abioticfactor: script("/opt/abioticfactor", [
    sc("Game files", "/opt/abioticfactor/gamefiles"),
    sc("Saves", "/opt/abioticfactor/data"),
  ]),
  corekeeper: script("/opt/corekeeper", [
    sc("Save data", "/opt/corekeeper/data"),
    sc("Game files and mods", "/opt/corekeeper/files"),
  ]),
  icarus: script("/opt/icarus", [sc("Save data and config", "/opt/icarus/data"), sc("Game", "/opt/icarus/game")]),
  arkasa: script("/opt/arkasa", undefined, "The one mount maps to the container's ShooterGame/Saved folder: saves and config, not the game install."),
  soulmask: script("/opt/soulmask"),
  dst: script("/opt/dst"),
  vintagestory: script("/opt/vintagestory", [sc("Data and config", "/opt/vintagestory/data")]),
  necesse: script("/opt/necesse", undefined, "The mount is the game's config/save folder (~/.config/Necesse)."),
  tf2: script("/opt/tf2", [sc("Config", "/opt/tf2/tf/cfg")]),
