s=s.replace('''  return <FileBrowser key={api.key + (linked ?? "")} api={api} initialPath={linked ?? initialPath} />;''','''  /* A game server lands in its game folder (not "/"); a deep link or explicit initialPath wins. */
  return <FileBrowser key={api.key + (linked ?? "")} api={api} initialPath={linked ?? initialPath ?? gameFiles?.path} gameFiles={gameFiles} />;''',1)
open(p,'w').write(s)
