import { test } from "node:test";
import assert from "node:assert/strict";
import { GAME_FAMILIES } from "../lib/games";
import {
  GAME_FILES_ROOTS, gameFilesFor, isInsideGameFolder, nearestExistingParent, normalizeBrowserPath,
} from "../lib/game-files-roots";
import { GAME_CONTROL } from "../lib/game-control";

const isClean = (p: string) => p.startsWith("/") && !p.includes("..") && !p.includes("//") && (p === "/" || !p.endsWith("/")) && !/\/\.(\/|$)/.test(p) && /^[A-Za-z0-9._/-]+$/.test(p);

test("every game family has a files-root entry (a new game cannot ship without one)", () => {
  for (const f of GAME_FAMILIES) {
    const e = GAME_FILES_ROOTS[f];
    assert.ok(e, `lib/game-files-roots.ts has no entry for "${f}"`);
    assert.ok(e.label.length > 0);
    assert.ok(["verified-live", "from-setup-script"].includes(e.source));
  }
  assert.deepEqual(Object.keys(GAME_FILES_ROOTS).sort(), [...GAME_FAMILIES].sort(), "no stale families either");
});

test("all paths are absolute, normalised and free of '..'", () => {
  for (const f of GAME_FAMILIES) {
    const e = GAME_FILES_ROOTS[f];
    assert.ok(isClean(e.gameFilesPath), `${f}: ${e.gameFilesPath}`);
    assert.notEqual(e.gameFilesPath, "/", `${f}: landing must not be the OS root`);
    assert.equal(normalizeBrowserPath(e.gameFilesPath), e.gameFilesPath);
    for (const s of e.extraShortcuts ?? []) {
      assert.ok(isClean(s.path), `${f} shortcut ${s.label}: ${s.path}`);
      assert.ok(s.label.length > 0);
    }
  }
});

test("shortcuts are unique per family and live beside the game's own /opt folders", () => {
  for (const f of GAME_FAMILIES) {
    const e = GAME_FILES_ROOTS[f];
    const paths = (e.extraShortcuts ?? []).map((s) => s.path);
    assert.equal(new Set(paths).size, paths.length, `${f}: duplicate shortcut`);
    assert.ok(e.gameFilesPath.startsWith("/opt/"), `${f}: expected under /opt`);
  }
});

test("landing folder is consistent with GAME_CONTROL.dataRoots (same /opt family tree)", () => {
  for (const f of GAME_FAMILIES) {
    const spec = GAME_CONTROL[f];
    if (!spec) continue;
    const landing = GAME_FILES_ROOTS[f].gameFilesPath;
    const top = (p: string) => p.split("/").slice(0, 3).join("/");
    const roots = spec.dataRoots.filter((r) => r.startsWith("/opt/"));
    if (roots.length) assert.ok(roots.some((r) => top(r) === top(landing)), `${f}: landing ${landing} vs dataRoots ${roots.join(",")}`);
  }
});

test("variant filtering of shortcuts", () => {
  const paper = gameFilesFor("minecraft", "paper")!;
  assert.deepEqual(paper.shortcuts.map((s) => s.label), ["Plugins", "World", "Config"]);
  const fabric = gameFilesFor("minecraft", "fabric")!;
  assert.deepEqual(fabric.shortcuts.map((s) => s.label), ["Mods", "World", "Config"]);
  assert.deepEqual(gameFilesFor("minecraft", "vanilla")!.shortcuts.map((s) => s.label), ["World", "Config"]);
  assert.deepEqual(gameFilesFor("minecraft", null)!.shortcuts.map((s) => s.label), ["World", "Config"]);
  assert.ok(gameFilesFor("valheim", "bepinex")!.shortcuts.some((s) => s.label.startsWith("Mods")));
  assert.ok(!gameFilesFor("valheim", "vanilla")!.shortcuts.some((s) => s.label.startsWith("Mods")));
  assert.equal(gameFilesFor("valheim", "vanilla")!.path, "/opt/valheim/config");
});

test("gameFilesFor returns null for non-game / unknown families", () => {
  assert.equal(gameFilesFor(null), null);
  assert.equal(gameFilesFor("docker"), null);
  assert.equal(gameFilesFor("wordpress"), null);
  assert.equal(gameFilesFor("__proto__"), null);
  assert.equal(gameFilesFor("constructor"), null);
});

test("isInsideGameFolder: whole segments, trailing slashes, siblings", () => {
  assert.equal(isInsideGameFolder("/opt/mc", "/opt/mc"), true);
  assert.equal(isInsideGameFolder("/opt/mc/", "/opt/mc"), true);
  assert.equal(isInsideGameFolder("/opt/mc", "/opt/mc/"), true);
  assert.equal(isInsideGameFolder("/opt/mc/plugins", "/opt/mc"), true);
  assert.equal(isInsideGameFolder("/opt/mc/plugins/", "/opt/mc/"), true);
  assert.equal(isInsideGameFolder("//opt//mc/world", "/opt/mc"), true);
  assert.equal(isInsideGameFolder("/opt/mc-old", "/opt/mc"), false);
  assert.equal(isInsideGameFolder("/opt/mc-old/world", "/opt/mc"), false);
  assert.equal(isInsideGameFolder("/opt/mcx", "/opt/mc"), false);
  assert.equal(isInsideGameFolder("/opt", "/opt/mc"), false);
  assert.equal(isInsideGameFolder("/", "/opt/mc"), false);
  assert.equal(isInsideGameFolder("/etc", "/opt/mc"), false);
  assert.equal(isInsideGameFolder("/etc", "/"), true);
  // landing folders that are themselves nested (valheim): sibling mounts are OS-side
  assert.equal(isInsideGameFolder("/opt/valheim/data", "/opt/valheim/config"), false);
  assert.equal(isInsideGameFolder("/opt/valheim/config/worlds_local", "/opt/valheim/config"), true);
});

test("nearestExistingParent walks up to the deepest existing folder", async () => {
  const existing = new Set(["/", "/opt", "/opt/mc"]);
  const exists = async (p: string) => existing.has(p);
  assert.equal(await nearestExistingParent("/opt/mc", exists), "/opt/mc");
  assert.equal(await nearestExistingParent("/opt/mc/plugins", exists), "/opt/mc");
  assert.equal(await nearestExistingParent("/opt/mc/plugins/deep/er/", exists), "/opt/mc");
  assert.equal(await nearestExistingParent("/opt/valheim/config/bepinex", exists), "/opt");
  assert.equal(await nearestExistingParent("/srv/x", exists), "/");
  assert.equal(await nearestExistingParent("/srv/x", async () => false), null);
  const probed: string[] = [];
  await nearestExistingParent("/a/b/c", async (p) => { probed.push(p); return false; });
  assert.deepEqual(probed, ["/a/b/c", "/a/b", "/a", "/"]);
});
EOF
