"use client";
// THROWAWAY screenshot harness (not committed): FileBrowser against an in-memory fake guest.
import { useMemo } from "react";
import { FileBrowser } from "@/components/customer/files/FileBrowser";
import { gameFilesFor } from "@/lib/game-files-roots";
import type { FileApi, FileEntry } from "@/lib/files-types";

const T = 1790000000000;
const d = (name: string): FileEntry => ({ name, isDirectory: true, size: 0, modifiedMs: T, mode: "755" });
const f = (name: string, size: number): FileEntry => ({ name, isDirectory: false, size, modifiedMs: T, mode: "644" });
const FS: Record<string, FileEntry[]> = {
  "/": ["bin","boot","dev","etc","home","opt","root","srv","usr","var"].map(d),
  "/etc": [d("apt"), d("docker"), d("systemd"), f("fstab", 412), f("hostname", 14), f("passwd", 1800)],
  "/opt": [d("mc"), d("containerd")],
  "/opt/mc": [d("config"), d("libraries"), d("logs"), d("plugins"), d("versions"), d("world"), f("eula.txt", 9), f("paper.yml", 5120), f("server.properties", 1204), f("ops.json", 2), f("whitelist.json", 2)],
  "/opt/mc/plugins": [f("EssentialsX.jar", 2400000), f("Vault.jar", 120000), d("Essentials")],
  "/opt/mc/world": [d("region"), d("data"), f("level.dat", 3000)],
  "/opt/mc/config": [f("paper-global.yml", 4000)],
  "/root": [f(".bashrc", 3106), d(".ssh")],
};
export default function Page() {
  const sp = typeof window !== "undefined" ? new URLSearchParams(window.location.search) : new URLSearchParams();
  const mode = sp.get("mode") ?? "game";
  const start = sp.get("start") ?? undefined;
  const info = mode === "game" ? gameFilesFor("minecraft", "paper") : null;
  const api: FileApi = useMemo(() => ({
    key: "fake-" + mode, rootLabel: "root",
    list: async (p) => (FS[p] ? { ok: true as const, entries: FS[p] } : { ok: false as const, error: "No such file or directory" }),
    read: async () => ({ ok: true as const, content: "" }),
    save: async () => ({ ok: true as const }), mkdir: async () => ({ ok: true as const }),
    rename: async () => ({ ok: true as const }), remove: async () => ({ ok: true as const }),
    uploadUrl: () => "/x", downloadUrl: (p) => "/x" + p,
  }), [mode]);
  return (
    <div style={{ padding: 16, maxWidth: 1200, margin: "0 auto" }}>
      <h1 style={{ color: "#fff", fontWeight: 700, marginBottom: 12 }}>Files</h1>
      <FileBrowser key={mode + (start ?? "")} api={api} initialPath={start ?? info?.path ?? "/"} gameFiles={info} />
    </div>
  );
}
