export type GameFilesGuide = {
  kind: GuideKind;
  /** About three words. */
  title: string;
  /** One honest sentence. Never promises something the platform does not do. */
  description: string;
  path: string;
  /** Only offer this guide on these `Server.gameVariant` values (lower-case). Omit = every variant. */
  variants?: string[];
  /** The folder is made later (first start, first install, first backup): the card says so. Navigation still works via the nearest-existing-parent fallback. */
  createdLater?: boolean;
  /** Evidence: "live" = `test -d` found it on a real running server (2026-10-05); "absent" = probed on a real server and not there yet (see note); "script" = derived from setup script / applier / installer. */
  evidence: "live" | "absent" | "script";
  /** Developer note (why absent, where derived from). Not shown to customers. */
  note?: string;
};

