export const GAME_FILES_ROOTS: Record<GameFamily, GameFilesRoot> = Object.fromEntries(
  GAME_FAMILIES.map((f) => {
    const d = DEFS[f];
    return [f, {
      ...d,
      label: GAME_DISPLAY[f]?.name ?? f,
      extraShortcuts: d.guides.map((g) => ({ label: g.title, path: g.path, ...(g.variants ? { variants: g.variants } : {}) })),
    }];
  }),
) as Record<GameFamily, GameFilesRoot>;

/** What the Files tab needs for one server: serializable, variant-filtered. null for non-game / unknown families. */
export type GameFilesInfo = {
  family: string;
  label: string;
  path: string;
  /** Ordered guides that apply to this server's variant. */
  guides: GameFilesGuide[];
  /** Chips derived from `guides` (excluding the landing folder itself and the advanced install/log folders). */
  shortcuts: GameFilesShortcut[];
};

export function guidesForVariant(guides: GameFilesGuide[], variant?: string | null): GameFilesGuide[] {
  const v = (variant ?? "").toLowerCase();
  return guides.filter((g) => !g.variants || (v !== "" && g.variants.includes(v)));
}

export function gameFilesFor(family: string | null | undefined, variant?: string | null): GameFilesInfo | null {
  if (!family || !Object.prototype.hasOwnProperty.call(GAME_FILES_ROOTS, family)) return null;
  const r = GAME_FILES_ROOTS[family as GameFamily];
  const guides = guidesForVariant(r.guides, variant);
  const shortcuts = guides
    .filter((g) => g.kind !== "install" && g.kind !== "logs" && g.path !== r.gameFilesPath)
    .map((g) => ({ label: g.title, path: g.path }));
  return { family, label: r.label, path: r.gameFilesPath, guides, shortcuts };
}

/** The 2 to 3 most useful guides for the OS-warning banner: saves, then plugins/mods/add-ons, then config. */
export function topGuides(guides: GameFilesGuide[], max = 3): GameFilesGuide[] {
  const order: GuideKind[] = ["saves", "plugins", "mods", "addons", "config"];
  const out: GameFilesGuide[] = [];
  for (const k of order) {
    const g = guides.find((x) => x.kind === k && !out.includes(x));
    if (g && out.length < max) out.push(g);
  }
  return out;
}

