"use client";

import { useEffect, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { isInsideGameArea, topGuides, type GameFilesGuide, type GameFilesInfo, type GuideKind } from "@/lib/game-files-roots";

const KIND_ICON: Record<GuideKind, string> = {
  saves: "database", config: "sliders", plugins: "plussq", mods: "cube", addons: "layers",
  backups: "archive", install: "server", logs: "filesearch", other: "folder",
};

/** Collapsed by default on a phone-width screen, open on desktop. Set after mount so server and first client render agree. */
function useCollapsible() {
  const [open, setOpen] = useState(true);
  useEffect(() => {
    try { if (window.matchMedia("(max-width: 639px)").matches) setOpen(false); } catch { /* keep open */ }
  }, []);
  return [open, setOpen] as const;
}

function GuideCard({ g, onGo, compact }: { g: GameFilesGuide; onGo: (path: string) => void; compact?: boolean }) {
  return (
    <li data-testid="guide-card" data-kind={g.kind}
        className={"flex min-w-0 flex-col gap-1.5 rounded-[12px] border border-rim-hi bg-[rgba(3,9,24,.55)] " + (compact ? "p-2.5" : "p-3")}>
      <div className="flex min-w-0 items-center gap-2">
        <Icon name={KIND_ICON[g.kind]} size={14} tone="inherit" className="flex-none text-[#7fb0ff]" />
        <h3 className="min-w-0 truncate text-[12.5px] font-bold text-white">{g.title}</h3>
      </div>
      <p className="text-[12px] leading-snug text-tx-dim">{g.description}</p>
      {g.createdLater && (
        <p className="text-[11px] leading-snug text-tx-faint">
          {g.kind === "backups" ? "Created when you make your first backup." : "Created when the server first starts or the add-on is installed."}
        </p>
      )}
      <p className="truncate font-mono text-[10.5px] text-tx-faint" title={g.path}>{g.path}</p>
      <button type="button" onClick={() => onGo(g.path)} aria-label={`Open ${g.title}: ${g.path}`}
              className="mt-auto self-start rounded-[8px] border border-rim-hi bg-well px-3 py-1 text-[11.5px] font-semibold text-white transition hover:border-brand-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
        Open
      </button>
    </li>
  );
}

function Toggle({ open, onClick, label, controls }: { open: boolean; onClick: () => void; label: string; controls: string }) {
  return (
    <button type="button" onClick={onClick} aria-expanded={open} aria-controls={controls}
            className="flex items-center gap-1.5 rounded-[8px] px-1.5 py-1 text-[12px] font-bold text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
      <span aria-hidden className={"inline-block text-tx-faint transition " + (open ? "rotate-90" : "")}>&#9656;</span>
      {label}
    </button>
  );
}

/**
 * The game-server Files tab's orientation strip.
 *
 * The file browser is a view of the guest's whole filesystem, and a customer poking around in
 * "/" or "/etc" is looking at the operating system, not their game. This does the following and
 * nothing else:
 *   - inside the game's area: says so, and shows "Where to find things": one card per guide
 *     (saves, plugins/mods, config...) saying what the folder is for, each with an Open button;
 *   - outside it: a clear, NON-BLOCKING warning with a one-click jump to the game files and the
 *     2 to 3 most useful guides (dismissible; the jump button and chips stay after);
 *   - it only navigates. Every read/write still goes through the existing authenticated file API;
 *     nothing here widens what that API allows.
 */
export function GameFilesBar({
  info,
  path,
  onGo,
  warningDismissed,
  onDismissWarning,
}: {
  info: GameFilesInfo;
  path: string;
  /** Navigate the browser to an absolute path (the browser resolves a missing folder to its nearest existing parent). */
  onGo: (path: string) => void;
  warningDismissed: boolean;
  onDismissWarning: () => void;
}) {
  const inside = isInsideGameArea(path, info);
  const [open, setOpen] = useCollapsible();

  const chips = info.shortcuts.length > 0 && (
    <ul className="flex flex-wrap items-center gap-1.5" aria-label={`${info.label} folders`}>
      {info.shortcuts.map((s) => (
        <li key={s.path + s.label}>
          <button type="button" onClick={() => onGo(s.path)} title={s.path}
                  className="rounded-full border border-rim-hi bg-well px-2.5 py-1 text-[11.5px] font-semibold text-tx-dim transition hover:border-brand-400 hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
            {s.label}
          </button>
        </li>
      ))}
    </ul>
  );

  if (inside) {
    return (
      <section data-testid="game-files-bar" aria-label={`${info.label} game files`}
               className="rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3.5 py-2.5">
        <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
          <span className="flex min-w-0 items-center gap-2 text-[12.5px] font-semibold text-white">
            <Icon name="gamepad" size={14} tone="inherit" className="flex-none text-[#7fb0ff]" />
            <span>{info.label} game files</span>
          </span>
          <Toggle open={open} onClick={() => setOpen(!open)} label="Where to find things" controls="game-guides" />
          <button type="button" onClick={() => onGo("/")}
                  className="ml-auto flex-none rounded-[8px] px-2 py-1 text-[11.5px] font-semibold text-tx-faint underline-offset-2 transition hover:text-white hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
            Operating system files
          </button>
        </div>
        {open && info.guides.length > 0 && (
          <ul id="game-guides" className="mt-2.5 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
            {info.guides.map((g) => <GuideCard key={g.path + g.title} g={g} onGo={onGo} />)}
          </ul>
        )}
      </section>
    );
  }

  const openBtn = (
    <button type="button" onClick={() => onGo(info.path)}
            className="nx-cta inline-flex flex-none items-center gap-1.5 rounded-[9px] bg-gradient-to-r from-[#3b6be8] to-[#7b3fef] px-3.5 py-1.5 text-[12.5px] font-semibold text-white shadow-[0_0_18px_rgba(91,80,240,.35)] transition hover:brightness-110 focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
      <Icon name="gamepad" size={13} tone="inherit" /> Open {info.label} files
    </button>
  );

  if (warningDismissed) {
    return (
      <div data-testid="game-files-bar" className="flex flex-wrap items-center gap-x-3 gap-y-2 rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3.5 py-2.5">
        {openBtn}
        {chips}
      </div>
    );
  }

  const top = topGuides(info.guides);
  return (
    <div data-testid="os-files-warning" role="note"
         className="rounded-[14px] border border-amber-500/35 bg-amber-500/10 px-3.5 py-3">
      <div className="flex items-start gap-2.5">
        <Icon name="warntriangle" size={16} tone="inherit" className="mt-0.5 flex-none text-amber-300" />
        <p className="min-w-0 flex-1 text-[12.5px] leading-relaxed text-amber-100">
          <span className="font-semibold">You are viewing the server&apos;s operating system files.</span>{" "}
          Be careful: changing or deleting files here can break your server. Your game files are here:
        </p>
        <button type="button" onClick={onDismissWarning} aria-label="Dismiss this warning"
                className="flex-none text-amber-200/70 transition hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
          <Icon name="xcircle" size={15} tone="inherit" />
        </button>
      </div>
      <div className="mt-2.5 pl-[26px]">
        <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
          {openBtn}
          {top.length > 0 && <Toggle open={open} onClick={() => setOpen(!open)} label="Where to find things" controls="game-guides-top" />}
        </div>
        {open && top.length > 0 && (
          <ul id="game-guides-top" className="mt-2.5 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
            {top.map((g) => <GuideCard key={g.path + g.title} g={g} onGo={onGo} compact />)}
          </ul>
        )}
      </div>
    </div>
  );
}

