        <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
          <span className="flex min-w-0 items-center gap-2 text-[12.5px] font-semibold text-white">
            <Icon name="gamepad" size={14} tone="inherit" className="flex-none text-[#7fb0ff]" />
            <span>{info.label} game files</span>
          </span>
          <Toggle open={open} onClick={() => setOpen(!open)} label="Where to find things" controls="game-guides" />
          <button type="button" onClick={() => onGo("/")}
                  className="ml-auto flex-none rounded-[8px] px-2 py-1 text-[11.5px] font-semibold text-tx-faint underline-offset-2 transition hover:text-white hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
            Operating system files
          </button>
        </div>
        {open && info.guides.length > 0 && (
          <ul id="game-guides" className="mt-2.5 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
            {info.guides.map((g) => <GuideCard key={g.path + g.title} g={g} onGo={onGo} />)}
          </ul>
        )}
      </section>
    );
  }

  const openBtn = (
    <button type="button" onClick={() => onGo(info.path)}
            className="nx-cta inline-flex flex-none items-center gap-1.5 rounded-[9px] bg-gradient-to-r from-[#3b6be8] to-[#7b3fef] px-3.5 py-1.5 text-[12.5px] font-semibold text-white shadow-[0_0_18px_rgba(91,80,240,.35)] transition hover:brightness-110 focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
      <Icon name="gamepad" size={13} tone="inherit" /> Open {info.label} files
    </button>
  );

  if (warningDismissed) {
    return (
      <div data-testid="game-files-bar" className="flex flex-wrap items-center gap-x-3 gap-y-2 rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3.5 py-2.5">
        {openBtn}
        {chips}
      </div>
    );
  }

  const top = topGuides(info.guides);
  return (
    <div data-testid="os-files-warning" role="note"
         className="rounded-[14px] border border-amber-500/35 bg-amber-500/10 px-3.5 py-3">
      <div className="flex items-start gap-2.5">
        <Icon name="warntriangle" size={16} tone="inherit" className="mt-0.5 flex-none text-amber-300" />
        <p className="min-w-0 flex-1 text-[12.5px] leading-relaxed text-amber-100">
          <span className="font-semibold">You are viewing the server&apos;s operating system files.</span>{" "}
          Be careful: changing or deleting files here can break your server. Your game files are here:
        </p>
        <button type="button" onClick={onDismissWarning} aria-label="Dismiss this warning"
                className="flex-none text-amber-200/70 transition hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
          <Icon name="xcircle" size={15} tone="inherit" />
        </button>
      </div>
      <div className="mt-2.5 pl-[26px]">
        <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
          {openBtn}
          {top.length > 0 && <Toggle open={open} onClick={() => setOpen(!open)} label="Where to find things" controls="game-guides-top" />}
        </div>
        {open && top.length > 0 && (
          <ul id="game-guides-top" className="mt-2.5 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
            {top.map((g) => <GuideCard key={g.path + g.title} g={g} onGo={onGo} compact />)}
          </ul>
        )}
      </div>
    </div>
  );
}

