/* The portal's loading state.
 *
 * Mounted through Next's route-segment `loading.tsx`, so it replaces the page
 * body (never the shell) until that route's server component has finished —
 * these pages are `force-dynamic` and several wait on real work (IMAP on Mail,
 * Mailcow discovery on Mailboxes, Stripe on Billing).
 *
 * THE MARK is the marketing site's animated NX logo (app/nxm/_aurora/runtime.ts
 * `NX` paths + `.au-logo` in app/nxm/aurora.css: outline draws, gradient fill
 * lands, a sheen crosses it). Marketing plays that once on scroll; a loader has
 * to repeat, so the same three phases are re-timed here as one seamless loop —
 * every animated property is back at its 0% value by 100%. Same geometry, same
 * #1B6BFF → #3D5BFF → #6B3BFF gradient, same skewed white sheen.
 *
 * Server-rendered and CSS-only — no client component, no hydration — because it
 * is on screen exactly while the page's own JavaScript is not ready.
 *
 * Timing, all CSS (see `.nx-pre*` in app/globals.css):
 *   - The whole thing fades in after 140ms. A navigation that resolves faster
 *     than that never shows a loader at all, so quick pages don't flicker
 *     through one. Nothing waits on this — content replaces it the instant the
 *     route streams in.
 *   - After ~8s a "still loading" line fades in — on a slow connection the
 *     customer gets told something instead of watching a loop forever. (A real
 *     failure is not this component's job: it hands off to app/dashboard/
 *     error.tsx the moment the route throws.)
 *   - prefers-reduced-motion: the mark is drawn filled and still.
 *
 * The box is a fixed size, so neither the fade-in nor the late hint line can
 * shift anything around it.
 */

/** The NX lettermark — the exact three paths the marketing runtime ships. */
const NX_W = 133;
const NX_H = 64;
const NX_PATHS = [
  "M91.38 46.38 L91.75 47.62 L106.62 63.88 L126.25 63.88 L125.88 62.62 L102.00 36.88 L101.12 36.75 Z",
  "M132.00 0.00 L112.12 0.00 L92.50 19.00 L92.25 19.88 L101.38 29.88 L102.38 29.88 L131.12 1.50 Z",
  "M0.00 63.88 L15.88 63.88 L20.88 21.75 L21.50 20.75 L54.00 61.75 L55.50 62.88 L56.88 63.25 L57.25 63.88 L66.62 63.88 L66.75 63.38 L69.62 61.88 L98.38 33.62 L98.38 32.88 L78.50 11.12 L68.88 1.25 L66.62 0.50 L66.38 0.00 L49.00 0.00 L49.50 1.50 L78.00 32.62 L77.38 33.75 L63.50 47.50 L62.88 47.62 L24.88 0.00 L10.88 0.00 L10.50 0.62 L8.50 1.25 L7.62 2.50 L0.50 61.00 L0.00 61.38 Z",
];

/** The animated mark on its own, for any other place that wants the loader look. */
export function NxLoaderMark({ width = 112 }: { width?: number }) {
  return (
    <svg
      className="nx-pre-mark"
      viewBox={`-1 -1 ${NX_W + 2} ${NX_H + 2}`}
      width={width}
      height={Math.round((width * (NX_H + 2)) / (NX_W + 2))}
      aria-hidden
      focusable="false"
    >
      <defs>
        <linearGradient id="nxpre-g" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#1B6BFF" />
          <stop offset=".55" stopColor="#3D5BFF" />
          <stop offset="1" stopColor="#6B3BFF" />
        </linearGradient>
        <linearGradient id="nxpre-s" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#fff" stopOpacity="0" />
          <stop offset=".5" stopColor="#fff" stopOpacity=".75" />
          <stop offset="1" stopColor="#fff" stopOpacity="0" />
        </linearGradient>
        <clipPath id="nxpre-c">
          {NX_PATHS.map((d) => <path key={d} d={d} />)}
        </clipPath>
      </defs>
      {NX_PATHS.map((d) => <path key={"f" + d} className="nx-pre-f" d={d} fill="url(#nxpre-g)" />)}
      <g clipPath="url(#nxpre-c)">
        {/* The skew stays on the rect; the sweep animates the group, so the
            CSS transform never overwrites the skew attribute. */}
        <g className="nx-pre-sh">
          <rect x="0" y="-2" width={NX_W * 0.45} height={NX_H + 4} fill="url(#nxpre-s)" transform="skewX(-18)" />
        </g>
      </g>
      {NX_PATHS.map((d) => (
        <path key={"o" + d} className="nx-pre-o" d={d} pathLength={100} fill="none" stroke="url(#nxpre-g)" strokeWidth={0.9} strokeLinejoin="round" />
      ))}
    </svg>
  );
}

export function Preloader({ label = "Loading" }: { label?: string }) {
  return (
    <div className="nx-pre grid h-full w-full place-items-center" role="status" aria-live="polite">
      <div className="nx-pre-box relative flex flex-col items-center">
        <span className="nx-pre-glow" aria-hidden />
        <NxLoaderMark />
        <span className="nx-pre-slow" aria-hidden>
          Still loading — this is taking longer than usual.
        </span>
        <span className="sr-only">{label}</span>
      </div>
    </div>
  );
}
import { Preloader } from "@/components/nx/Preloader";

/* Route-segment loading state for EVERY page under /dashboard.
 *
 * It replaces a grey skeleton (a pulsing bar, four pulsing tiles, one pulsing
 * slab) that was doing the opposite of its job: it guessed a layout most of
 * these pages do not have, so a route flashed a wrong-shaped grey wireframe and
 * then re-laid-out into the real thing — the "half the content, then the other
 * half" effect, with an extra jump on top.
 *
 * This sits below app/dashboard/layout.tsx, so the shell — rail, header,
 * balance — stays put and only the content area swaps. The chrome never
 * flashes, and the page body never arrives in two instalments.
 *
 * One honest limit: it covers navigation between portal pages and reloads of
 * any page under this segment. It cannot cover the layout's OWN first render
 * (session lookup, nav badges) on a cold load, because a segment's loading
 * state renders inside its layout — the layout has to resolve before there is
 * anywhere to put it.
 */
export default function DashboardLoading() {
  return <Preloader />;
}
