// Pure helpers for the shared file browser (components/customer/files/*): path-bar segmenting,
// the double-click guard and the per-browser listing cache. No React, no server imports, so it is
// unit-tested directly (test/files-nav.test.ts).

import type { FileEntry } from "./files-types";

export type PathSegment = { label: string; path: string };

/**
 * "/opt/terraria/backups/" -> [{opt,/opt},{terraria,/opt/terraria},{backups,/opt/terraria/backups}].
 * Root and "" give no segments. Repeated and trailing slashes collapse; "." segments are dropped;
 * spaces and unicode are kept as typed. ".." is NOT resolved here (the file API rejects it).
 */
export function pathSegments(path: string): PathSegment[] {
  const parts = String(path ?? "").split("/").filter((s) => s !== "" && s !== ".");
  return parts.map((label, i) => ({ label, path: "/" + parts.slice(0, i + 1).join("/") }));
}

/** Canonical "/a/b" form ("/" for root) used as the cache key and for comparisons. */
export function canonicalPath(path: string): string {
  return "/" + pathSegments(path).map((s) => s.label).join("/");
}

/**
 * The friendly label shown beside the path bar: "Game files > backups" when `path` is inside
 * `gameRoot`, otherwise null. Whole-segment comparison, so /opt/mc-old is not inside /opt/mc.
 */
export function friendlyPathLabel(path: string, gameRoot: string | null | undefined, rootName = "Game files"): string | null {
  if (!gameRoot) return null;
  const p = pathSegments(path).map((s) => s.label);
  const r = pathSegments(gameRoot).map((s) => s.label);
  if (r.length === 0 || p.length < r.length || r.some((x, i) => p[i] !== x)) return null;
  return [rootName, ...p.slice(r.length)].join(" > ");
}

/**
 * Double-click guard: a press on a control whose target is already the one being opened is
 * ignored; a different target always wins (it supersedes the pending one).
 */
export function shouldStartNav(pending: string | null, target: string): boolean {
  return pending === null || canonicalPath(pending) !== canonicalPath(target);
}

export type CachedListing = { entries: FileEntry[]; at: number };

/**
 * Stale-while-revalidate listing cache. Keyed by scope + canonical path, where the scope is the
 * file source's identity (FileApi.key, which embeds the server/account id), so one server's
 * listing can never be served for another. An instance lives in ONE mounted browser (never a
 * module singleton), so it cannot outlive a sign-out/sign-in in the same tab either. Entries
 * expire after `ttlMs` (an expired entry is simply a miss) and the oldest are dropped past `max`.
 */
export class ListingCache {
  private m = new Map<string, CachedListing>();
  constructor(private opts: { max?: number; ttlMs?: number; now?: () => number } = {}) {}
  private now() { return (this.opts.now ?? Date.now)(); }
  private key(scope: string, path: string) { return `${scope}\u0000${canonicalPath(path)}`; }
  get(scope: string, path: string): CachedListing | null {
    const k = this.key(scope, path);
    const v = this.m.get(k);
    if (!v) return null;
    if (this.now() - v.at > (this.opts.ttlMs ?? 120_000)) { this.m.delete(k); return null; }
    return v;
  }
  set(scope: string, path: string, entries: FileEntry[]) {
    const k = this.key(scope, path);
    this.m.delete(k);
    this.m.set(k, { entries, at: this.now() });
    const max = this.opts.max ?? 80;
    while (this.m.size > max) this.m.delete(this.m.keys().next().value as string);
  }
  /** Drop everything for one source (after a write: upload, rename, delete, extract...). */
  clearScope(scope: string) {
    const prefix = `${scope}\u0000`;
    for (const k of [...this.m.keys()]) if (k.startsWith(prefix)) this.m.delete(k);
  }
  clear() { this.m.clear(); }
  get size() { return this.m.size; }
}

/** Friendly text for a failed read of a folder. */
export function describeListError(message: string): { missing: boolean; text: string } {
  const missing = /no such|not found|does not exist/i.test(message);
  return { missing, text: missing ? "That folder doesn't exist." : message };
}
