/**
 * A tiny keyed connection pool with an idle timeout, used by lib/sftp.ts for READ operations
 * (list, read) so that browsing folders does not pay an SSH handshake (~150-350 ms measured) on
 * every click.
 *
 * SECURITY MODEL (the reason it is shaped this way):
 *  - The pool is only reached from server code AFTER the caller's session, ownership and path
 *    validation have been checked on every single call (lib/actions-files.ts). The pool saves the
 *    TCP/SSH handshake and nothing else: it never skips an authorisation check.
 *  - The key embeds the authenticated USER id, the server id, the connection target and a
 *    fingerprint of the credential, so a connection opened for user A is never handed to user B,
 *    never reused for another server, and is abandoned when the credential rotates.
 *  - Connections idle out (default 25 s), are capped in number (oldest idle evicted), are closed on
 *    any 'close'/'error' event, and are dropped on a connection-type error (never reused after one).
 *  - Operations on one connection are serialised, so two requests never interleave on a channel.
 *
 * Generic over the client type and free of I/O imports so the keying/expiry logic is unit-tested
 * with fake timers and a fake client (test/sftp-pool.test.ts).
 */
export type PoolOpts<C> = {
  idleMs?: number;
  maxEntries?: number;
  close: (c: C) => Promise<void> | void;
};

type Entry<C> = { conn: C; timer: ReturnType<typeof setTimeout> | null; queue: Promise<unknown>; lastUsed: number; uses: number };

export class ConnPool<C> {
  private entries = new Map<string, Entry<C>>();
  private pending = new Map<string, Promise<Entry<C>>>();
  constructor(private opts: PoolOpts<C>) {}

  get size() { return this.entries.size; }
  has(key: string) { return this.entries.has(key); }

  private idleMs() { return this.opts.idleMs ?? 25_000; }

  private arm(key: string, e: Entry<C>) {
    if (e.timer) clearTimeout(e.timer);
    e.timer = setTimeout(() => this.evict(key, e), this.idleMs());
    (e.timer as { unref?: () => void }).unref?.();
  }

  /** Close and forget an entry (only if it is still the registered one). */
  evict(key: string, only?: Entry<C>) {
    const e = this.entries.get(key);
    if (!e || (only && e !== only)) return;
    this.entries.delete(key);
    if (e.timer) clearTimeout(e.timer);
    try { void Promise.resolve(this.opts.close(e.conn)).catch(() => {}); } catch { /* best effort */ }
  }

  /** Mark a connection dead from outside (the client's own 'close'/'error' event). */
  drop(key: string, conn: C) {
    const e = this.entries.get(key);
    if (e && e.conn === conn) this.evict(key, e);
  }

  closeAll() { for (const k of [...this.entries.keys()]) this.evict(k); }

  private async acquire(key: string, connect: () => Promise<C>): Promise<{ e: Entry<C>; reused: boolean }> {
    const existing = this.entries.get(key);
    if (existing) return { e: existing, reused: true };
    let p = this.pending.get(key);
    if (!p) {
      p = connect().then((conn) => {
        const e: Entry<C> = { conn, timer: null, queue: Promise.resolve(), lastUsed: Date.now(), uses: 0 };
        this.entries.set(key, e);
        this.trim(key);
        return e;
      }).finally(() => { this.pending.delete(key); });
      this.pending.set(key, p);
    }
    return { e: await p, reused: false };
  }

  private trim(keep: string) {
    const max = this.opts.maxEntries ?? 32;
    while (this.entries.size > max) {
      let oldestKey: string | null = null; let oldest = Infinity;
      for (const [k, v] of this.entries) if (k !== keep && v.lastUsed < oldest) { oldest = v.lastUsed; oldestKey = k; }
      if (oldestKey === null) break;
      this.evict(oldestKey);
    }
  }

  /**
   * Run `fn` on the pooled connection for `key`, opening one with `connect` when there is none.
   * A connection-type failure on a REUSED connection is retried once on a fresh one.
   */
  async run<T>(key: string, connect: () => Promise<C>, fn: (c: C) => Promise<T>, isConnError: (e: unknown) => boolean): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      const { e, reused } = await this.acquire(key, connect);
      if (e.timer) { clearTimeout(e.timer); e.timer = null; } // never idle-close mid-operation
      const job = e.queue.then(() => fn(e.conn));
      e.queue = job.catch(() => undefined);
      try {
        const out = await job;
        e.uses++; e.lastUsed = Date.now();
        if (this.entries.get(key) === e) this.arm(key, e);
        return out;
      } catch (err) {
        if (isConnError(err)) {
          this.evict(key, e);
          if (reused && attempt === 0) continue;
        } else if (this.entries.get(key) === e) {
          e.lastUsed = Date.now(); this.arm(key, e);
        }
        throw err;
      }
    }
  }
}

