"use client";

import { useEffect, useRef, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { isInsideGameArea, topGuides, type GameFilesGuide, type GameFilesInfo, type GuideKind } from "@/lib/game-files-roots";
import { canonicalPath } from "@/lib/files-nav";

const KIND_ICON: Record<GuideKind, string> = {
  saves: "database", config: "sliders", plugins: "plussq", mods: "cube", addons: "layers",
  backups: "archive", install: "server", logs: "filesearch", other: "folder",
};

const DETAILS_KEY = "nx-files-guide-details";

/** Small spinner; static under prefers-reduced-motion. */
function Spinner({ size = 12 }: { size?: number }) {
  return (
    <span aria-hidden className="inline-block flex-none animate-spin rounded-full border-2 border-current border-t-transparent motion-reduce:animate-none"
          style={{ width: size, height: size }} />
  );
}

type Tip = { text: string; x: number; y: number } | null;

/** Hover AND keyboard-focus tooltip, rendered position:fixed so a scrolling strip cannot clip it. */
function tipFor(el: HTMLElement, text: string): Tip {
  const r = el.getBoundingClientRect();
  const w = typeof window !== "undefined" ? window.innerWidth : 1200;
  return { text, x: Math.max(8, Math.min(r.left, w - 276)), y: r.bottom + 6 };
}

function GuideChip({
  g, onGo, opening, onPrefetch, setTip,
}: {
  g: GameFilesGuide; onGo: (p: string) => void; opening: boolean;
  onPrefetch: (p: string | null) => void; setTip: (t: Tip) => void;
}) {
  const label = `${g.title}. ${g.description}`;
  return (
    <button type="button"
            aria-label={opening ? `Opening ${g.title}` : label}
            aria-busy={opening}
            disabled={opening}
            onClick={() => onGo(g.path)}
            onMouseEnter={(e) => { setTip(tipFor(e.currentTarget, g.description)); onPrefetch(g.path); }}
            onMouseLeave={() => { setTip(null); onPrefetch(null); }}
            onFocus={(e) => setTip(tipFor(e.currentTarget, g.description))}
            onBlur={() => setTip(null)}
            className="inline-flex flex-none items-center gap-1.5 whitespace-nowrap rounded-full border border-rim-hi bg-well px-2.5 py-1 text-[11.5px] font-semibold text-tx-dim transition hover:border-brand-400 hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400 disabled:cursor-wait disabled:border-brand-400 disabled:text-white">
      {opening ? <Spinner size={11} /> : <Icon name={KIND_ICON[g.kind]} size={12} tone="inherit" className="flex-none text-[#7fb0ff]" />}
      {opening ? "Opening…" : g.title}
    </button>
  );
}

function GuideCard({
  g, onGo, opening, onPrefetch,
}: { g: GameFilesGuide; onGo: (p: string) => void; opening: boolean; onPrefetch: (p: string | null) => void }) {
  return (
    <li data-testid="guide-card" data-kind={g.kind}
        className="flex min-w-0 flex-col gap-1.5 rounded-[12px] border border-rim-hi bg-[rgba(3,9,24,.55)] p-3">
      <div className="flex min-w-0 items-center gap-2">
        <Icon name={KIND_ICON[g.kind]} size={14} tone="inherit" className="flex-none text-[#7fb0ff]" />
        <h3 className="min-w-0 truncate text-[12.5px] font-bold text-white">{g.title}</h3>
      </div>
      <p className="text-[12px] leading-snug text-tx-dim">{g.description}</p>
      {g.createdLater && (
        <p className="text-[11px] leading-snug text-tx-faint">
          {g.kind === "backups" ? "Created when you make your first backup." : "Created when the server first starts or the add-on is installed."}
        </p>
      )}
      <p className="truncate font-mono text-[10.5px] text-tx-faint" title={g.path}>{g.path}</p>
      <button type="button" onClick={() => onGo(g.path)} disabled={opening} aria-busy={opening}
              aria-label={opening ? `Opening ${g.title}` : `Open ${g.title}: ${g.path}`}
              onMouseEnter={() => onPrefetch(g.path)} onMouseLeave={() => onPrefetch(null)}
              className="mt-auto inline-flex items-center gap-1.5 self-start rounded-[8px] border border-rim-hi bg-well px-3 py-1 text-[11.5px] font-semibold text-white transition hover:border-brand-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400 disabled:cursor-wait disabled:border-brand-400">
        {opening ? <><Spinner size={11} /> Opening…</> : "Open"}
      </button>
    </li>
  );
}

/**
 * The game-server Files tab's orientation strip, kept SLIM so the file list stays on screen:
 *   - inside the game's area: ONE row (about 40px, horizontally scrollable on a phone): "Where to
 *     find things" + a chip per guide (icon + short title; the one-line description is a tooltip on
 *     hover AND keyboard focus and part of the accessible name) + a "Details" toggle that expands
 *     full explanatory cards (the choice is remembered per browser) + the "Operating system files"
 *     link;
 *   - outside it: a slim non-blocking warning (text + the main "Open <Game> files" button + at
 *     most 3 chips), dismissible; the button and chips stay in a compact row afterwards;
 *   - it only navigates. Every read/write still goes through the existing authenticated file API;
 *     nothing here widens what that API allows.
 * A control whose folder is being opened shows a spinner and "Opening…" and is disabled, so a
 * second click cannot start a second navigation.
 */
export function GameFilesBar({
  info, path, onGo, warningDismissed, onDismissWarning, openingPath = null, onPrefetch = () => {},
}: {
  info: GameFilesInfo;
  path: string;
  /** Navigate the browser to an absolute path (it resolves a missing folder to its nearest existing parent). */
  onGo: (path: string) => void;
  warningDismissed: boolean;
  onDismissWarning: () => void;
  /** The folder currently being opened, if any (drives the per-control spinner). */
  openingPath?: string | null;
  /** Hover prefetch: called with a path on pointer-enter, null on leave. */
  onPrefetch?: (path: string | null) => void;
}) {
  const inside = isInsideGameArea(path, info);
  const [details, setDetails] = useState(false);
  const [tip, setTip] = useState<Tip>(null);
  const loaded = useRef(false);
  useEffect(() => {
    try { setDetails(window.localStorage.getItem(DETAILS_KEY) === "1"); } catch { /* storage blocked: stays collapsed */ }
    loaded.current = true;
  }, []);
  const toggleDetails = () => {
    const next = !details;
    setDetails(next);
    try { window.localStorage.setItem(DETAILS_KEY, next ? "1" : "0"); } catch { /* best effort */ }
  };
  const isOpening = (p: string) => !!openingPath && canonicalPath(openingPath) === canonicalPath(p);

  const tooltip = tip && (
    <div role="tooltip" className="pointer-events-none fixed z-50 max-w-[260px] rounded-[8px] border border-rim-hi bg-surface px-2.5 py-1.5 text-[11.5px] leading-snug text-white shadow-2xl"
         style={{ left: tip.x, top: tip.y }}>
      {tip.text}
    </div>
  );

  const chip = (g: GameFilesGuide) => (
    <GuideChip key={g.path + g.title} g={g} onGo={onGo} opening={isOpening(g.path)} onPrefetch={onPrefetch} setTip={setTip} />
  );

  if (inside) {
    return (
      <section data-testid="game-files-bar" aria-label={`${info.label} game files`}
               className="rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3 py-1.5">
        <div className="flex h-[34px] items-center gap-2 overflow-x-auto whitespace-nowrap [scrollbar-width:thin]">
          <span className="flex flex-none items-center gap-1.5 text-[12px] font-bold text-white">
            <Icon name="gamepad" size={13} tone="inherit" className="text-[#7fb0ff]" />
            Where to find things
          </span>
          <span className="h-4 w-px flex-none bg-rim-hi" aria-hidden />
          {info.guides.map(chip)}
          <button type="button" onClick={toggleDetails} aria-expanded={details} aria-controls="game-guides"
                  className="inline-flex flex-none items-center gap-1 rounded-[8px] px-2 py-1 text-[11.5px] font-semibold text-tx-dim transition hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
            <span aria-hidden className={"inline-block text-tx-faint transition " + (details ? "rotate-90" : "")}>&#9656;</span>
            Details
          </button>
          <button type="button" onClick={() => onGo("/")} disabled={isOpening("/")} aria-busy={isOpening("/")}
                  onMouseEnter={() => onPrefetch("/")} onMouseLeave={() => onPrefetch(null)}
                  className="ml-auto inline-flex flex-none items-center gap-1.5 rounded-[8px] px-2 py-1 text-[11.5px] font-semibold text-tx-faint underline-offset-2 transition hover:text-white hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400 disabled:cursor-wait disabled:text-white">
            {isOpening("/") && <Spinner size={11} />}
            {isOpening("/") ? "Opening…" : "Operating system files"}
          </button>
        </div>
        {details && info.guides.length > 0 && (
          <ul id="game-guides" className="mt-2 mb-1 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
            {info.guides.map((g) => <GuideCard key={g.path + g.title} g={g} onGo={onGo} opening={isOpening(g.path)} onPrefetch={onPrefetch} />)}
          </ul>
        )}
        {tooltip}
      </section>
    );
  }

  const openBtn = (
    <button type="button" onClick={() => onGo(info.path)} disabled={isOpening(info.path)} aria-busy={isOpening(info.path)}
            onMouseEnter={() => onPrefetch(info.path)} onMouseLeave={() => onPrefetch(null)}
            className="nx-cta inline-flex flex-none items-center gap-1.5 whitespace-nowrap rounded-[9px] bg-gradient-to-r from-[#3b6be8] to-[#7b3fef] px-3.5 py-1.5 text-[12.5px] font-semibold text-white shadow-[0_0_18px_rgba(91,80,240,.35)] transition hover:brightness-110 focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400 disabled:cursor-wait disabled:opacity-90">
      {isOpening(info.path) ? <Spinner size={13} /> : <Icon name="gamepad" size={13} tone="inherit" />}
      {isOpening(info.path) ? "Opening…" : `Open ${info.label} files`}
    </button>
  );
  const top = topGuides(info.guides);

  if (warningDismissed) {
    return (
      <div data-testid="game-files-bar" className="flex items-center gap-2 overflow-x-auto whitespace-nowrap rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3 py-1.5">
        {openBtn}
        {top.map(chip)}
        {tooltip}
      </div>
    );
  }

  return (
    <div data-testid="os-files-warning" role="note"
         className="rounded-[14px] border border-amber-500/35 bg-amber-500/10 px-3 py-2">
      <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
        <p className="flex min-w-[240px] flex-1 items-start gap-2 text-[12px] leading-snug text-amber-100">
          <Icon name="warntriangle" size={15} tone="inherit" className="mt-px flex-none text-amber-300" />
          <span>
            <span className="font-semibold">You are viewing the server&apos;s operating system files.</span>{" "}
            Be careful: changing or deleting files here can break your server. Your game files are here:
          </span>
        </p>
        <div className="flex max-w-full items-center gap-2 overflow-x-auto whitespace-nowrap">
          {openBtn}
          {top.map(chip)}
        </div>
        <button type="button" onClick={onDismissWarning} aria-label="Dismiss this warning"
                className="flex-none text-amber-200/70 transition hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
          <Icon name="xcircle" size={15} tone="inherit" />
        </button>
      </div>
      {tooltip}
    </div>
  );
}

