"use client";

import { useEffect, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { isInsideGameArea, topGuides, type GameFilesGuide, type GameFilesInfo, type GuideKind } from "@/lib/game-files-roots";
import { canonicalPath } from "@/lib/files-nav";

const KIND_ICON: Record<GuideKind, string> = {
  saves: "database", config: "sliders", plugins: "plussq", mods: "cube", addons: "layers",
  backups: "archive", install: "server", logs: "filesearch", other: "folder",
};

const DETAILS_KEY = "nx-files-guide-details";

/** Small spinner; static under prefers-reduced-motion. */
function Spinner({ size = 12 }: { size?: number }) {
  return (
    <span aria-hidden className="inline-block flex-none animate-spin rounded-full border-2 border-current border-t-transparent motion-reduce:animate-none"
          style={{ width: size, height: size }} />
  );
}

type Tip = { text: string; x: number; y: number } | null;

/** Hover AND keyboard-focus tooltip, rendered position:fixed so a scrolling strip cannot clip it. */
function tipFor(el: HTMLElement, text: string): Tip {
  const r = el.getBoundingClientRect();
  const w = typeof window !== "undefined" ? window.innerWidth : 1200;
  return { text, x: Math.max(8, Math.min(r.left, w - 276)), y: r.bottom + 6 };
}

function GuideChip({
  g, onGo, opening, onPrefetch, setTip,
}: {
  g: GameFilesGuide; onGo: (p: string) => void; opening: boolean;
  onPrefetch: (p: string | null) => void; setTip: (t: Tip) => void;
}) {
  const label = `${g.title}. ${g.description}`;
  return (
    <button type="button"
            aria-label={opening ? `Opening ${g.title}` : label}
            aria-busy={opening}
            disabled={opening}
            onClick={() => onGo(g.path)}
            onMouseEnter={(e) => { setTip(tipFor(e.currentTarget, g.description)); onPrefetch(g.path); }}
            onMouseLeave={() => { setTip(null); onPrefetch(null); }}
            onFocus={(e) => setTip(tipFor(e.currentTarget, g.description))}
            onBlur={() => setTip(null)}
            className="inline-flex flex-none items-center gap-1.5 whitespace-nowrap rounded-full border border-rim-hi bg-well px-2.5 py-1 text-[11.5px] font-semibold text-tx-dim transition hover:border-brand-400 hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400 disabled:cursor-wait disabled:border-brand-400 disabled:text-white">
      {opening ? <Spinner size={11} /> : <Icon name={KIND_ICON[g.kind]} size={12} tone="inherit" className="flex-none text-[#7fb0ff]" />}
      {opening ? "Opening…" : g.title}
    </button>
  );
}

function GuideCard({
  g, onGo, opening, onPrefetch,
}: { g: GameFilesGuide; onGo: (p: string) => void; opening: boolean; onPrefetch: (p: string | null) => void }) {
  return (
    <li data-testid="guide-card" data-kind={g.kind}
        className="flex min-w-0 flex-col gap-1.5 rounded-[12px] border border-rim-hi bg-[rgba(3,9,24,.55)] p-3">
      <div className="flex min-w-0 items-center gap-2">
        <Icon name={KIND_ICON[g.kind]} size={14} tone="inherit" className="flex-none text-[#7fb0ff]" />
        <h3 className="min-w-0 truncate text-[12.5px] font-bold text-white">{g.title}</h3>
      </div>
      <p className="text-[12px] leading-snug text-tx-dim">{g.description}</p>
      {g.createdLater && (
        <p className="text-[11px] leading-snug text-tx-faint">
          {g.kind === "backups" ? "Created when you make your first backup." : "Created when the server first starts or the add-on is installed."}
        </p>
      )}
