              aria-label={opening ? `Opening ${g.title}` : `Open ${g.title}: ${g.path}`}
              onMouseEnter={() => onPrefetch(g.path)} onMouseLeave={() => onPrefetch(null)}
              className="mt-auto inline-flex items-center gap-1.5 self-start rounded-[8px] border border-rim-hi bg-well px-3 py-1 text-[11.5px] font-semibold text-white transition hover:border-brand-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400 disabled:cursor-wait disabled:border-brand-400">
        {opening ? <><Spinner size={11} /> Opening…</> : "Open"}
      </button>
    </li>
  );
}

