            <span aria-hidden className={"inline-block text-tx-faint transition " + (details ? "rotate-90" : "")}>&#9656;</span>
            Details
          </button>
          <button type="button" onClick={() => onGo("/")} disabled={isOpening("/")} aria-busy={isOpening("/")}
