  const top = topGuides(info.guides);

  if (warningDismissed) {
    return (
      <div data-testid="game-files-bar" className="flex items-center gap-2 overflow-x-auto whitespace-nowrap rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3 py-1.5">
        {openBtn}
        {top.map(chip)}
        {tooltip}
      </div>
    );
  }

  return (
    <div data-testid="os-files-warning" role="note"
         className="rounded-[14px] border border-amber-500/35 bg-amber-500/10 px-3 py-2">
