"use client";

import { useEffect, useRef, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { canonicalPath, pathSegments } from "@/lib/files-nav";

/**
 * The persistent path bar above the file list: the FULL absolute path of the current folder as
 * clickable segments, a copy-path button, and (inside a game's folder) a friendly label such as
 * "Game files > backups". One non-wrapping row: a long path scrolls sideways, kept scrolled to
 * its end so the current folder is always the visible part. It reads `path` directly, so it
 * updates the instant navigation starts (before the listing arrives).
 */
export function PathBar({
  path, rootText, onGo, onPrefetch, friendly, canCopy, openingPath,
}: {
  path: string;
  /** Text of the first segment: "/" for a server, the share's name for hosting. */
  rootText: string;
  onGo: (path: string) => void;
  onPrefetch?: (path: string | null) => void;
  friendly?: string | null;
  canCopy: boolean;
  openingPath?: string | null;
}) {
  const segs = pathSegments(path);
  const full = canonicalPath(path);
  const scroller = useRef<HTMLDivElement | null>(null);
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const el = scroller.current;
    if (el) el.scrollLeft = el.scrollWidth;
  }, [full]);
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);

  const copy = async () => {
    let ok = false;
    try { await navigator.clipboard.writeText(full); ok = true; } catch {
      try {
        const ta = document.createElement("textarea");
        ta.value = full; ta.setAttribute("readonly", ""); ta.style.position = "fixed"; ta.style.opacity = "0";
        document.body.appendChild(ta); ta.select(); ok = document.execCommand("copy"); document.body.removeChild(ta);
      } catch { /* give up quietly */ }
    }
    if (ok) {
      setCopied(true);
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(false), 1800);
    }
  };

  const seg = (label: string, p: string, last: boolean, text = label) => {
    const opening = !!openingPath && canonicalPath(openingPath) === canonicalPath(p);
    return (
      <button type="button" key={p} onClick={() => onGo(p)} aria-current={last ? "page" : undefined}
              onMouseEnter={() => onPrefetch?.(p)} onMouseLeave={() => onPrefetch?.(null)}
              className={"flex-none whitespace-nowrap rounded-[6px] px-1 py-0.5 font-mono text-[12.5px] transition focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400 " +
                (last ? "font-semibold text-white" : "text-tx-dim hover:bg-white/[0.06] hover:text-white") + (opening ? " animate-pulse motion-reduce:animate-none" : "")}>
        {text}
      </button>
    );
  };

  return (
    <nav aria-label="Current folder" data-testid="path-bar"
         className="flex h-[38px] items-center gap-2 rounded-[12px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-2.5">
      <Icon name="folder" size={13} tone="inherit" className="flex-none text-[#7fb0ff]" />
      <div ref={scroller} className="flex min-w-0 flex-1 items-center overflow-x-auto whitespace-nowrap [scrollbar-width:none]">
        {seg(rootText, "/", segs.length === 0, rootText)}
        {segs.map((s, i) => (
          <span key={s.path} className="flex flex-none items-center">
            {(i > 0 || rootText !== "/") && <span aria-hidden className="px-0.5 font-mono text-[12.5px] text-tx-faint">/</span>}
            {seg(s.label, s.path, i === segs.length - 1)}
          </span>
        ))}
      </div>
      {friendly && (
        <span data-testid="path-friendly" className="hidden flex-none rounded-full border border-rim-hi bg-well px-2.5 py-0.5 text-[11px] font-semibold text-[#9fc2ff] sm:inline-flex">
          {friendly}
        </span>
      )}
      {canCopy && (
        <button type="button" onClick={() => void copy()} aria-label={copied ? "Path copied" : `Copy path ${full}`}
                className="inline-flex h-[26px] flex-none items-center gap-1 rounded-[8px] border border-rim-hi px-2 text-[11px] font-semibold text-tx-dim transition hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand-400">
          <Icon name={copied ? "check" : "copy"} size={12} tone="inherit" />
          <span className="hidden sm:inline">{copied ? "Copied" : "Copy path"}</span>
        </button>
      )}
      <span className="sr-only" role="status" aria-live="polite">{copied ? "Path copied" : ""}</span>
    </nav>
  );
}

