import { PathBar } from "./PathBar";
import { NxLoaderMark } from "@/components/nx/Preloader";
import { isInsideGameFolder, nearestExistingParent, type GameFilesInfo } from "@/lib/game-files-roots";
import { ListingCache, canonicalPath, describeListError, friendlyPathLabel, shouldStartNav } from "@/lib/files-nav";
''')

# state
rep('''  /* Game servers only: the landing folder may not exist yet (still provisioning, game never
     started once). When the FIRST read of the landing folder fails, walk up to the nearest
     existing parent instead of showing an error. */
  const landingFallback = useRef(!!gameFiles && initialPath === gameFiles.path);''','''  /* Game servers only: the landing folder may not exist yet (still provisioning, game never
     started once). The FIRST read of the landing folder, and every game-files control, asks for
     the nearest existing parent when the folder is missing (ONE call, see FileApi.listNearest). */
  const fallbackNext = useRef(!!gameFiles && initialPath === gameFiles.path);
  const skipEffect = useRef<string | null>(null);
  const reqId = useRef(0);
  const openingRef = useRef<string | null>(null);''')
rep('''  const [entries, setEntries] = useState<FileEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);''','''  /* Per-mount stale-while-revalidate cache (see lib/files-nav.ts ListingCache: keyed by source +
     path, never shared across mounts, servers or sessions). */
  const cache = useRef(new ListingCache()).current;
  const [listing, setListing] = useState<{ path: string; entries: FileEntry[] } | null>(null);
  const entries = listing?.entries ?? [];
  const [loading, setLoading] = useState(true);
  const [listError, setListError] = useState<{ path: string; text: string; missing: boolean } | null>(null);
  const [fallbackNote, setFallbackNote] = useState<string | null>(null);
  const [openingPath, setOpeningPath] = useState<string | null>(null);
  const [announce, setAnnounce] = useState("");
  const [error, setError] = useState<string | null>(null);''')

# replace goTo..effect
a=s.index("  /* Go to a folder from a game-files control, falling back")
b=s.index("  const onUploadNotice = useCallback")
new='''  const scope = api.key;

  /** Read a folder. A cached listing renders instantly and is revalidated in the background. */
  const load = useCallback(async (p: string, o: { fallback?: boolean; force?: boolean } = {}) => {
    const id = ++reqId.current;
    const cached = o.force ? null : cache.get(scope, p);
    if (cached) { setListing({ path: p, entries: cached.entries }); setListError(null); setLoading(false); }
    else setLoading(true);
    setSelected([]);
    setAnnounce(`Opening ${p}`);
    const a = apiRef.current;
    type R = { ok: true; path: string; fellBack: boolean; entries: FileEntry[] } | { ok: false; error: string } | null;
    let res: R;
    if (o.fallback && a.listNearest) {
      res = await a.listNearest(p).catch(() => null);
    } else if (o.fallback) {
      let last: FileEntry[] | null = null;
      const dest = await nearestExistingParent(p, async (x) => {
        const r = await a.list(x).catch(() => null);
        if (r && r.ok) { last = r.entries; return true; }
        return false;
      });
      res = dest !== null && last ? { ok: true, path: dest, fellBack: dest !== p, entries: last } : { ok: false, error: "No such directory." };
    } else {
      const r = await a.list(p).catch(() => null);
      res = r && r.ok ? { ok: true, path: p, fellBack: false, entries: r.entries } : r;
    }
    if (id !== reqId.current) return; // superseded by a newer navigation
    openingRef.current = null;
    setOpeningPath(null);
    setLoading(false);
    if (!res || !res.ok) {
      const d = describeListError(res ? res.error : "Couldn't reach the server.");
      setListError({ path: p, text: d.text, missing: d.missing });
      setAnnounce(d.text);
      return;
    }
    cache.set(scope, res.path, res.entries);
    setListing({ path: res.path, entries: res.entries });
    setListError(null);
    setAnnounce(`Opened ${res.path}`);
    if (res.path !== p) {
      skipEffect.current = res.path;
      setPath(res.path);
      setFallbackNote(`${p} doesn't exist yet. It is created the first time it is needed, for example when the server first starts, an add-on is installed or a backup is made. Showing ${res.path} instead.`);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- api is read through a ref; `scope` is its identity; cache is stable
  }, [scope]);

  useEffect(() => {
    if (skipEffect.current === path) { skipEffect.current = null; return; }
    const fb = fallbackNext.current;
    fallbackNext.current = false;
    void load(path, { fallback: fb });
  }, [path, load]);

  /** After a write (upload, rename, delete, extract, save): drop this source's cache and re-read. */
  const refresh = useCallback(async () => {
    cache.clearScope(scope);
    await load(path, { force: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [load, path, scope]);

  /**
   * THE navigation entry point (rows, breadcrumbs, path bar, tree, ".." and every game-files
   * control). Optimistic: the path and path bar change at once; a cached listing shows instantly.
   * A press on the folder already being opened is ignored (double-click guard).
   */
  const go = useCallback((target: string, o: { fallback?: boolean } = {}) => {
    if (!shouldStartNav(openingRef.current, target)) return;
    setEditor(null);
    setFallbackNote(null);
    setError(null);
    if (canonicalPath(target) === canonicalPath(path)) {
      // Already here: re-read it, with the same visible feedback, rather than doing nothing.
      openingRef.current = target; setOpeningPath(target);
      void load(path, { force: true, fallback: o.fallback });
      return;
    }
    openingRef.current = target;
    setOpeningPath(target);
    fallbackNext.current = !!o.fallback;
    setPath(target);
  }, [load, path]);

  /* Hover prefetch: after the pointer rests on a folder for 150 ms, read it into the cache so the
     click renders instantly. Cancelled on leave; at most one every 400 ms (the list action is
     rate-limited per user). */
  const prefetchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastPrefetch = useRef(0);
  const prefetch = useCallback((p: string | null) => {
    if (prefetchTimer.current) { clearTimeout(prefetchTimer.current); prefetchTimer.current = null; }
    if (!p || cache.get(scope, p)) return;
    prefetchTimer.current = setTimeout(async () => {
      prefetchTimer.current = null;
      if (Date.now() - lastPrefetch.current < 400) return;
      lastPrefetch.current = Date.now();
      const r = await apiRef.current.list(p).catch(() => null);
      if (r && r.ok && !cache.get(scope, p)) cache.set(scope, p, r.entries);
    }, 150);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scope]);
  useEffect(() => () => { if (prefetchTimer.current) clearTimeout(prefetchTimer.current); }, []);

'''
s=s[:a]+new+s[b:]
open(p,'w').write(s)
