    if (skipEffect.current === path) { skipEffect.current = null; return; }
    const fb = fallbackNext.current;
    fallbackNext.current = false;
    void load(path, { fallback: fb });
  }, [path, load]);

  /** After a write (upload, rename, delete, extract, save): drop this source's cache and re-read. */
  const refresh = useCallback(async () => {
    cache.clearScope(scope);
    await load(path, { force: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [load, path, scope]);

  /**
   * THE navigation entry point (rows, breadcrumbs, path bar, tree, ".." and every game-files
   * control). Optimistic: the path and path bar change at once; a cached listing shows instantly.
   * A press on the folder already being opened is ignored (double-click guard).
   */
  const go = useCallback((target: string, o: { fallback?: boolean } = {}) => {
    if (!shouldStartNav(openingRef.current, target)) return;
    setEditor(null);
    setFallbackNote(null);
    setError(null);
    if (canonicalPath(target) === canonicalPath(path)) {
      // Already here: re-read it, with the same visible feedback, rather than doing nothing.
      openingRef.current = target; setOpeningPath(target);
      void load(path, { force: true, fallback: o.fallback });
      return;
    }
    openingRef.current = target;
    setOpeningPath(target);
    fallbackNext.current = !!o.fallback;
    setPath(target);
  }, [load, path]);

  /* Hover prefetch: after the pointer rests on a folder for 150 ms, read it into the cache so the
     click renders instantly. Cancelled on leave; at most one every 400 ms (the list action is
     rate-limited per user). */
  const prefetchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastPrefetch = useRef(0);
  const prefetch = useCallback((p: string | null) => {
    if (prefetchTimer.current) { clearTimeout(prefetchTimer.current); prefetchTimer.current = null; }
    if (!p || cache.get(scope, p)) return;
    prefetchTimer.current = setTimeout(async () => {
      prefetchTimer.current = null;
      if (Date.now() - lastPrefetch.current < 400) return;
      lastPrefetch.current = Date.now();
      const r = await apiRef.current.list(p).catch(() => null);
      if (r && r.ok && !cache.get(scope, p)) cache.set(scope, p, r.entries);
    }, 150);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scope]);
  useEffect(() => () => { if (prefetchTimer.current) clearTimeout(prefetchTimer.current); }, []);

