/**
 * First-run guided tours — the serialisable shapes.
 *
 * A tour is plain data (no functions, no JSX) so it can be built on the server
 * from the REAL server/plan/family facts and handed straight to the client
 * engine in components/nx/tour as a prop. See docs/TOURS.md.
 */

export type TourPlacement = "auto" | "top" | "bottom" | "left" | "right";

export type TourStep = {
  /** Stable id — used for analytics-free resume (`lastStep` is an index, this is for authors/tests). */
  id: string;
  title: string;
  /** One or two short sentences. Plain text. */
  body: string;
  /** Optional short bullet list rendered under the body. Keep to ≤4. */
  bullets?: string[];
  /**
   * `data-tour` id of the element to spotlight. Omitted → a centred card with
   * no spotlight (intro/outro steps).
   */
  target?: string;
  /**
   * `data-tour` ids of controls to CLICK, in order, before the target is looked
   * up — this is how a step switches the panel to a tab and then to a settings
   * section. A control that already reports itself active (`aria-current` /
   * `aria-pressed="true"`) is not clicked again.
   */
  navigate?: string[];
  placement?: TourPlacement;
  /**
   * When the target can't be found (feature not on this plan, server offline,
   * element hidden at this breakpoint): `true` → silently skip the step;
   * otherwise the step still shows, as a centred card without a spotlight.
   */
  optional?: boolean;
  /** Only shown when the tour starts automatically (the one-time "it's ready" moment). */
  autoOnly?: boolean;
  /** Draws the celebratory variant (confetti burst + check). */
  celebrate?: boolean;
};

export type TourDef = {
  /** The serviceKey this tour belongs to (`vps`, `game:minecraft`, …). */
  key: string;
  /** Human name of the tour, e.g. "Minecraft server tour". */
  title: string;
  steps: TourStep[];
};

export type TourStatus = "STARTED" | "COMPLETED" | "DISMISSED";

/** What the client needs to know about a user's history with one tour. */
export type TourProgressView = {
  status: TourStatus;
  lastStep: number;
} | null;
/**
 * Game-server tours — one per family that has genuinely distinct features, and
 * a solid generic tour (still capability-aware) for every other family.
 *
 * Every claim here is checked against the real panel:
 *   - tabs + sub-tabs:   components/customer/gamepanel/v2/GamePanelShell.tsx
 *   - settings sections: components/customer/gamepanel/v2/GameSettingsShell.tsx
 *   - game settings form + "restart" tags + server type: components/customer/GameSettings.tsx
 *   - which families can push settings live: lib/game-config.ts REAL_APPLY_FAMILIES
 *   - which have a remote console / player list: lib/game-control.ts (rcon: "source")
 *   - which have one-click mod installs: lib/mod-install-support.ts INSTALLABLE_FAMILIES
 *   - subdomains: page.tsx network section (minecraft, bedrock, HOSTNAME_CONNECT_FAMILIES)
 * If one of those changes, the context flags below change with it — the copy
 * is chosen from the flags, never hard-coded per family where a flag exists.
 *
