/**
 * Server-side read of a user's tour state, for the mounts in
 * components/nx/tour/*Mount.tsx. Reads only; writes go through
 * lib/tours/actions.ts.
 */

import { currentUser, impersonating } from "@/lib/auth";
import { db } from "@/lib/db";
import { shouldAutoStart, TOUR_OPT_OUT_KEY } from "./trigger";

export type TourMountState = {
  /** Open the tour by itself on this load. */
  autoStart: boolean;
  /** Step index to open on when auto-starting (resume after an interrupted run). */
  resumeAt: number;
  /** A brand-new run (show the one-time "it's ready" step). */
  fresh: boolean;
  /** Whether the engine should write progress at all (owner, not impersonating). */
  persist: boolean;
};

export async function tourStateFor(input: {
  serviceKey: string;
  ownerId: string;
  ready: boolean;
  createdAt: Date;
  interstitial?: boolean;
}): Promise<TourMountState> {
  const [user, imp] = await Promise.all([currentUser(), impersonating()]);
  const none: TourMountState = { autoStart: false, resumeAt: 0, fresh: false, persist: false };
  if (!user) return none;
  const isOwner = user.id === input.ownerId;
  const persist = isOwner && !imp;
  if (!persist) return none;

  // Two tiny indexed reads; the unique (userId, serviceKey) index covers both.
  // A failure here (e.g. the table not yet migrated on an environment) must
  // never break the server page — no tour is the safe answer.
  let rows: { serviceKey: string; status: string; lastStep: number }[] = [];
  try {
    rows = await db.userTourProgress.findMany({
      where: { userId: user.id, serviceKey: { in: [input.serviceKey, TOUR_OPT_OUT_KEY] } },
      select: { serviceKey: true, status: true, lastStep: true },
    });
  } catch {
    return { ...none, persist: false };
  }
  const progress = rows.find((r) => r.serviceKey === input.serviceKey) ?? null;
  const optedOut = rows.some((r) => r.serviceKey === TOUR_OPT_OUT_KEY);
  const d = shouldAutoStart({
    isOwner,
    impersonating: !!imp,
    ready: input.ready,
    interstitial: input.interstitial,
    progress,
    lastStep: progress?.lastStep,
    optedOut,
    createdAt: input.createdAt,
  });
  return d.start
    ? { autoStart: true, resumeAt: d.resumeAt, fresh: d.fresh, persist }
    : { autoStart: false, resumeAt: 0, fresh: false, persist };
}
