/**
 * The game tour's "Find your files" steps. Everything a bullet says comes from the SAME data the
 * Files tab uses (lib/game-files-roots.ts guides, filtered by this server's variant), so the tour
 * can never recommend a folder the Files tab does not. Pure data + string building.
 */
import type { TourStep } from "./types";
import { gameFilesFor, type GameFilesGuide, type GameFilesInfo, type GuideKind } from "../game-files-roots";

/** Display names for variant ids in the "server type" nudge. */
const VARIANT_NAME: Record<string, string> = {
  paper: "Paper", purpur: "Purpur", fabric: "Fabric", forge: "Forge", bepinex: "BepInEx", oxide: "Oxide", carbon: "Carbon", metamod: "Metamod",
};
/** Server types the Settings picker lists but cannot actually be chosen (Rust Carbon: "isn't available on our Rust servers yet"). */
const NOT_OFFERED = new Set(["carbon"]);

const ADDON_KINDS: GuideKind[] = ["plugins", "mods", "addons"];

function bulletFor(g: GameFilesGuide): string {
  const later = g.createdLater
    ? g.kind === "backups"
      ? " It is created with your first backup."
      : " It is created the first time you start the server or install one."
    : "";
  return `${g.title}: ${g.path}. ${g.description}${later}`;
}

/**
 * At most 4 bullets, by priority: world saves, plugins/mods/add-ons (only what this game/variant
 * really has), config, the root game folder, backups.
 */
export function filesGuideBullets(info: GameFilesInfo): string[] {
  const g = info.guides;
  const picked: string[] = [];
  const used = new Set<GameFilesGuide>();
  const take = (x: GameFilesGuide | undefined) => { if (x && !used.has(x)) { used.add(x); picked.push(bulletFor(x)); } };
  take(g.find((x) => x.kind === "saves"));
  take(g.find((x) => x.kind === "plugins") ?? g.find((x) => x.kind === "mods") ?? g.find((x) => x.kind === "addons"));
  take(g.find((x) => x.kind === "config"));
  const rootCovered = g.some((x) => x.path === info.path && used.has(x));
  const rootBullet = rootCovered ? null : `Game folder: ${info.path}. The main folder for your server's files.`;
  const backups = g.find((x) => x.kind === "backups");
  const order: (string | null)[] = [rootBullet, backups ? bulletFor(backups) : null];
  for (const b of order) if (b && picked.length < 4) picked.push(b);
  return picked;
}

/** "Paper or Purpur" for the variants of the add-on guides this server's type doesn't have. */
function missingAddonTypes(family: string, info: GameFilesInfo, serverTypeLabels: string[]): { kinds: string; names: string } | null {
  const full = gameFilesFor(family, "\u0000");
  void full;
  return null as never;
}
