import type { TourStep } from "./types";
import { GAME_FILES_ROOTS, gameFilesFor, type GameFilesGuide, type GameFilesInfo } from "../game-files-roots";
import type { GameFamily } from "../games";

/** Display names for variant ids in the "server type" nudge. */
const VARIANT_NAME: Record<string, string> = {
  paper: "Paper", purpur: "Purpur", fabric: "Fabric", forge: "Forge", bepinex: "BepInEx", oxide: "Oxide", carbon: "Carbon", metamod: "Metamod",
};
/** Listed by the Settings picker but not selectable (Rust Carbon: "isn't available on our Rust servers yet"). */
const NOT_OFFERED = new Set(["carbon"]);

function bulletFor(g: GameFilesGuide): string {
  const later = g.createdLater
    ? g.kind === "backups"
      ? " It is created with your first backup."
      : " It is created the first time you start the server or install one."
    : "";
  return `${g.title}: ${g.path}. ${g.description}${later}`;
}

/**
 * At most 4 bullets, by priority: world saves, plugins/mods/add-ons (only what this game/variant
 * really has), config, the root game folder, backups. Each starts with a guide's own
 * "<title>: <path>" (or "Game folder: <landing path>").
 */
export function filesGuideBullets(info: GameFilesInfo): string[] {
  const g = info.guides;
  const picked: string[] = [];
  const used = new Set<GameFilesGuide>();
  const take = (x: GameFilesGuide | undefined) => { if (x && !used.has(x)) { used.add(x); picked.push(bulletFor(x)); } };
  take(g.find((x) => x.kind === "saves"));
  take(g.find((x) => x.kind === "plugins") ?? g.find((x) => x.kind === "mods") ?? g.find((x) => x.kind === "addons"));
  take(g.find((x) => x.kind === "config"));
  const rootCovered = g.some((x) => x.path === info.path && used.has(x));
  const backups = g.find((x) => x.kind === "backups");
  const rest: (string | null)[] = [rootCovered ? null : `Game folder: ${info.path}. The main folder for your server's files.`, backups ? bulletFor(backups) : null];
  for (const b of rest) if (b && picked.length < 4) picked.push(b);
  return picked;
}

/**
 * For a server type that has no plugins/mods folder while another SELECTABLE type of the same game
 * does (Minecraft Vanilla -> Paper/Fabric, Valheim Vanilla -> BepInEx), the names of those types and
 * what they unlock; null otherwise. `serverTypeLabels` is what the Settings server-type picker really
 * lists, so this never promises a type the panel does not offer.
 */
export function addonNudge(family: string, variant: string | null | undefined, serverTypeLabels: string[]): { names: string[]; what: string } | null {
  if (!Object.prototype.hasOwnProperty.call(GAME_FILES_ROOTS, family)) return null;
  const all = GAME_FILES_ROOTS[family as GameFamily].guides.filter((g) => ["plugins", "mods", "addons"].includes(g.kind) && g.variants);
  if (all.length === 0) return null;
  const v = (variant ?? "").toLowerCase();
  if (all.some((g) => g.variants!.includes(v))) return null; // this type already has one
  const offered = (id: string) => !NOT_OFFERED.has(id) && serverTypeLabels.some((l) => l.toLowerCase().startsWith(id));
  const ids = [...new Set(all.flatMap((g) => g.variants!))].filter(offered);
  if (ids.length === 0) return null;
  const kinds = new Set(all.filter((g) => g.variants!.some(offered)).map((g) => g.kind));
  const what = kinds.has("plugins") && kinds.has("mods") ? "plugins or mods" : kinds.has("plugins") ? "plugins" : "mods";
  return { names: ids.map((id) => VARIANT_NAME[id] ?? id), what };
}

function joinOr(xs: string[]): string {
  return xs.length <= 1 ? (xs[0] ?? "") : xs.length === 2 ? `${xs[0]} or ${xs[1]}` : `${xs.slice(0, -1).join(", ")} or ${xs[xs.length - 1]}`;
}

/** The two Files-tab steps that follow the generic "files" step. */
export function filesGuideSteps(ctx: { family: string; gameName: string; variant?: string | null; variants: string[] }): TourStep[] {
  const info = gameFilesFor(ctx.family, ctx.variant);
  if (!info) return [];
  const g = ctx.gameName;
  const nudge = addonNudge(ctx.family, ctx.variant, ctx.variants);
  const body =
    `Your ${g} files are one click away: the shortcuts here jump straight to the right folder.` +
    (nudge ? ` Your server type doesn't use ${nudge.what}; the ${joinOr(nudge.names)} server type in Settings does.` : "");
  return [
    {
      id: "files-guides",
      title: `Find your ${g} files`,
      body,
      bullets: filesGuideBullets(info),
      navigate: ["tab-files"],
      target: "files-guides",
      placement: "bottom",
    },
    {
      id: "files-os",
      title: "The operating system files",
      body: `Going up to / shows the server's own operating system files; an amber warning appears there, and “Open ${g} files” brings you back. The path bar always shows exactly where you are, with a copy button.`,
      navigate: ["tab-files"],
      target: "files-os-link",
      placement: "bottom",
    },
  ];
}
