import { test } from "node:test";
import assert from "node:assert/strict";
import { ListingCache, canonicalPath, describeListError, friendlyPathLabel, pathSegments, shouldStartNav } from "../lib/files-nav";
import type { FileEntry } from "../lib/files-types";

const E = (name: string): FileEntry => ({ name, isDirectory: false, size: 1, modifiedMs: 0, mode: null });

test("pathSegments: root, trailing/duplicate slashes, spaces, unicode", () => {
  assert.deepEqual(pathSegments("/"), []);
  assert.deepEqual(pathSegments(""), []);
  assert.deepEqual(pathSegments("/opt/terraria/backups/").map((s) => s.path), ["/opt", "/opt/terraria", "/opt/terraria/backups"]);
  assert.deepEqual(pathSegments("//opt///mc/./world").map((s) => s.label), ["opt", "mc", "world"]);
  assert.deepEqual(pathSegments("/home/my games/Wörld ★").map((s) => s.label), ["home", "my games", "Wörld ★"]);
  assert.equal(pathSegments("/home/my games/Wörld ★")[2]!.path, "/home/my games/Wörld ★");
  assert.equal(canonicalPath("/opt/mc/"), "/opt/mc");
  assert.equal(canonicalPath("opt//mc"), "/opt/mc");
  assert.equal(canonicalPath("/"), "/");
});

test("friendlyPathLabel: whole segments only", () => {
  assert.equal(friendlyPathLabel("/opt/terraria", "/opt/terraria"), "Game files");
  assert.equal(friendlyPathLabel("/opt/terraria/backups", "/opt/terraria"), "Game files > backups");
  assert.equal(friendlyPathLabel("/opt/terraria/backups/old/", "/opt/terraria/"), "Game files > backups > old");
  assert.equal(friendlyPathLabel("/opt/terraria-plugins", "/opt/terraria"), null);
  assert.equal(friendlyPathLabel("/etc", "/opt/terraria"), null);
  assert.equal(friendlyPathLabel("/opt", "/opt/terraria"), null);
  assert.equal(friendlyPathLabel("/opt/terraria", null), null);
});

test("double-click guard: same target ignored while opening, a different target wins", () => {
  assert.equal(shouldStartNav(null, "/opt/mc"), true);
  assert.equal(shouldStartNav("/opt/mc", "/opt/mc"), false);
  assert.equal(shouldStartNav("/opt/mc", "/opt/mc/"), false);
  assert.equal(shouldStartNav("/opt/mc", "/opt/mc/plugins"), true);
  assert.equal(shouldStartNav("/opt/mc", "/"), true);
});

test("ListingCache: keyed by scope+path, never leaks across servers, canonical paths", () => {
  const c = new ListingCache();
  c.set("server:A", "/opt/mc", [E("a")]);
  assert.equal(c.get("server:A", "/opt/mc/")!.entries[0]!.name, "a");
  assert.equal(c.get("server:B", "/opt/mc"), null, "another server must miss");
  assert.equal(c.get("server:A", "/opt/mc/world"), null);
  c.set("server:B", "/opt/mc", [E("b")]);
  assert.equal(c.get("server:A", "/opt/mc")!.entries[0]!.name, "a");
  assert.equal(c.get("server:B", "/opt/mc")!.entries[0]!.name, "b");
  // a scope that merely starts with another scope's text is a different scope
  c.set("server:A1", "/x", [E("z")]);
  c.clearScope("server:A");
  assert.equal(c.get("server:A", "/opt/mc"), null);
  assert.equal(c.get("server:A1", "/x")!.entries[0]!.name, "z");
  assert.equal(c.get("server:B", "/opt/mc")!.entries[0]!.name, "b");
});

test("ListingCache: ttl expiry and size cap", () => {
  let t = 1000;
  const c = new ListingCache({ ttlMs: 100, max: 2, now: () => t });
  c.set("s", "/a", [E("a")]);
  t += 99; assert.ok(c.get("s", "/a"));
  t += 2; assert.equal(c.get("s", "/a"), null);
  c.set("s", "/1", []); c.set("s", "/2", []); c.set("s", "/3", []);
  assert.equal(c.size, 2);
  assert.equal(c.get("s", "/1"), null);
  assert.ok(c.get("s", "/3"));
});

test("describeListError", () => {
  assert.deepEqual(describeListError("No such directory."), { missing: true, text: "That folder doesn't exist." });
  assert.equal(describeListError("Too many requests").missing, false);
});
