cat > test/sftp-pool.test.ts <<'EOF'
import { test, mock } from "node:test";
import assert from "node:assert/strict";
import { ConnPool, isConnectionError } from "../lib/sftp-pool";

type Conn = { id: number; closed: boolean };
function setup(opts: { idleMs?: number; maxEntries?: number } = {}) {
  let n = 0;
  const made: Conn[] = [];
  const pool = new ConnPool<Conn>({ ...opts, close: (c) => { c.closed = true; } });
  const connect = async () => { const c = { id: ++n, closed: false }; made.push(c); return c; };
  return { pool, connect, made };
}

test("same key reuses one connection; different keys never share", async () => {
  const { pool, connect, made } = setup();
  const k = (user: string, server: string) => `${user}:${server}|host:22|fp`;
  const seen: number[] = [];
  const use = (key: string) => pool.run(key, connect, async (c) => { seen.push(c.id); return c.id; }, isConnectionError);
  await use(k("u1", "s1")); await use(k("u1", "s1")); await use(k("u1", "s1"));
  assert.deepEqual(seen, [1, 1, 1]);
  await use(k("u2", "s1")); // another USER, same server: a new connection
  await use(k("u1", "s2")); // same user, another server: a new connection
  await use(k("u1", "s1|rotated"));
  assert.deepEqual(seen, [1, 1, 1, 2, 3, 4]);
  assert.equal(made.length, 4);
  pool.closeAll();
});

test("idle expiry closes the connection (fake timers); activity resets the timer", async () => {
  mock.timers.enable({ apis: ["setTimeout"] });
  try {
    const { pool, connect, made } = setup({ idleMs: 1000 });
    await pool.run("k", connect, async () => 1, isConnectionError);
    assert.equal(pool.size, 1);
    mock.timers.tick(900);
    await pool.run("k", connect, async () => 1, isConnectionError); // resets the idle timer
    mock.timers.tick(900);
    assert.equal(pool.size, 1);
    assert.equal(made[0]!.closed, false);
    mock.timers.tick(200);
    assert.equal(pool.size, 0);
    assert.equal(made[0]!.closed, true);
    await pool.run("k", connect, async () => 1, isConnectionError);
    assert.equal(made.length, 2, "after expiry a fresh connection is opened");
    pool.closeAll();
  } finally { mock.timers.reset(); }
});

test("a connection-type error evicts and retries once on a fresh connection; a normal sftp error keeps the connection", async () => {
  const { pool, connect, made } = setup();
  await pool.run("k", connect, async () => 1, isConnectionError);
  let calls = 0;
  const r = await pool.run("k", connect, async (c) => { calls++; if (c.id === 1) throw new Error("Not connected"); return c.id; }, isConnectionError);
  assert.equal(r, 2); assert.equal(calls, 2); assert.equal(made[0]!.closed, true);
  await assert.rejects(pool.run("k", connect, async () => { throw new Error("No such file"); }, isConnectionError), /No such file/);
  assert.equal(pool.has("k"), true, "ENOENT must not drop a healthy connection");
  assert.equal(made.length, 2);
  pool.closeAll();
});

test("operations on one connection are serialised; concurrent opens share one connect", async () => {
  const { pool, connect, made } = setup();
  const order: string[] = [];
  const job = (name: string, ms: number) => pool.run("k", connect, async () => { order.push(name + ":start"); await new Promise((r) => setTimeout(r, ms)); order.push(name + ":end"); }, isConnectionError);
  await Promise.all([job("a", 20), job("b", 1), job("c", 1)]);
  assert.deepEqual(order, ["a:start", "a:end", "b:start", "b:end", "c:start", "c:end"]);
  assert.equal(made.length, 1);
  pool.closeAll();
});

test("max entries evicts the least recently used and drop() forgets a dead connection", async () => {
  const { pool, connect, made } = setup({ maxEntries: 2 });
  await pool.run("a", connect, async () => 1, isConnectionError);
  await new Promise((r) => setTimeout(r, 2));
  await pool.run("b", connect, async () => 1, isConnectionError);
  await new Promise((r) => setTimeout(r, 2));
  await pool.run("c", connect, async () => 1, isConnectionError);
  assert.equal(pool.size, 2);
  assert.equal(pool.has("a"), false);
  assert.equal(made[0]!.closed, true);
  pool.drop("b", made[1]!);
  assert.equal(pool.has("b"), false);
  pool.drop("c", { id: 99, closed: false }); // not the registered connection: ignored
  assert.equal(pool.has("c"), true);
  pool.closeAll();
});

test("isConnectionError separates dead connections from normal answers", () => {
  for (const m of ["Not connected", "No SFTP connection available", "read ECONNRESET", "write EPIPE", "Timed out while waiting for handshake", "Channel closed"]) assert.equal(isConnectionError(new Error(m)), true, m);
  for (const m of ["No such file", "list: No such file /x", "Permission denied", "Not a directory", "Failure"]) assert.equal(isConnectionError(new Error(m)), false, m);
});
