"use client";
// THROWAWAY screenshot harness (not committed): the REAL FileBrowser (+ real tour engine) over an in-memory fake guest built from the guides.
import { useMemo } from "react";
import { FileBrowser } from "@/components/customer/files/FileBrowser";
import { TourLauncher } from "@/components/nx/tour/TourLauncher";
import { gameFilesFor } from "@/lib/game-files-roots";
import { buildGameTour } from "@/lib/tours/game";
import type { FileApi, FileEntry } from "@/lib/files-types";

const T = 1790000000000;
const d = (name: string): FileEntry => ({ name, isDirectory: true, size: 0, modifiedMs: T, mode: "755" });
const f = (name: string, size: number): FileEntry => ({ name, isDirectory: false, size, modifiedMs: T, mode: "644" });
export default function Page() {
  const sp = typeof window !== "undefined" ? new URLSearchParams(window.location.search) : new URLSearchParams();
  const family = sp.get("family") ?? "minecraft";
  const variant = sp.get("variant");
  const start = sp.get("start") ?? undefined;
  const fresh = sp.get("fresh") === "1";
  const delay = Number(sp.get("delay") ?? 0);
  const deep = sp.get("deep");
  const showTour = sp.get("tour") === "1";
  const info = family === "vps" ? null : gameFilesFor(family, variant);
  const api: FileApi = useMemo(() => {
    const dirs = new Set<string>(["/", "/bin", "/etc", "/home", "/opt", "/root", "/srv", "/usr", "/var"]);
    const add = (p: string) => { let c = p; while (c && c !== "/") { dirs.add(c); c = c.slice(0, c.lastIndexOf("/")); } };
    if (info) { add(info.path); for (const g of info.guides) if (!(fresh && g.createdLater)) add(g.path); }
    if (deep) add(deep);
    const files: Record<string, FileEntry[]> = { "/etc": [f("fstab", 412), f("hostname", 14)], "/root": [f(".bashrc", 3106)] };
    if (info) files[info.path] = [f("server.properties", 1204), f("eula.txt", 9), f("ops.json", 2)];
    const wait = () => new Promise((r) => setTimeout(r, delay));
    const listIt = (p: string) => {
      const kids = [...dirs].filter((x) => x !== p && x.startsWith(p === "/" ? "/" : p + "/") && !x.slice(p === "/" ? 1 : p.length + 1).includes("/")).map((x) => d(x.slice(x.lastIndexOf("/") + 1)));
      return [...kids, ...(files[p] ?? [])];
    };
    return {
      key: "server:fake-" + family, rootLabel: "root",
      list: async (p) => { await wait(); return dirs.has(p) ? { ok: true as const, entries: listIt(p) } : { ok: false as const, error: "No such directory." }; },
      listNearest: async (p) => {
        await wait();
        let cur = p;
        for (;;) { if (dirs.has(cur)) return { ok: true as const, path: cur, fellBack: cur !== p, entries: listIt(cur) }; const up = cur.slice(0, cur.lastIndexOf("/")); cur = up || "/"; }
      },
      read: async () => ({ ok: true as const, content: "" }),
      save: async () => ({ ok: true as const }), mkdir: async () => ({ ok: true as const }),
      rename: async () => ({ ok: true as const }), remove: async () => ({ ok: true as const }),
      uploadUrl: () => "/x", downloadUrl: (p) => "/x" + p,
    };
  }, [family, fresh, info, delay, deep]);
  const labels: Record<string, string[]> = { minecraft: ["Vanilla", "Paper", "Purpur", "Fabric", "Forge"], valheim: ["Vanilla", "BepInEx"] };
  const tour = info ? buildGameTour({
    family, gameName: info.label, hasGameSettings: true, canApply: false, variants: labels[family] ?? [], hasVersion: false, rcon: false,
    logTracked: false, modsInstallable: false, subdomain: false, isFree: false, variant,
  }) : null;
  const filesTour = tour ? { ...tour, steps: tour.steps.filter((s) => s.id.startsWith("files-")) } : null;
  return (
    <div style={{ padding: 16, maxWidth: 1200, margin: "0 auto" }}>
      <div className="flex items-center gap-3" style={{ marginBottom: 12 }}>
        <h1 style={{ color: "#fff", fontWeight: 700 }}>Files</h1>
        <button data-tour="tab-files" aria-current="page" className="rounded border border-rim-hi px-2 py-1 text-[12px] text-white">Files tab</button>
        {showTour && filesTour && <TourLauncher tour={filesTour} autoStart={false} persist={false} />}
      </div>
      <FileBrowser key={family + (variant ?? "") + (start ?? "") + fresh + delay} api={api} initialPath={start ?? info?.path ?? "/"} gameFiles={info} />
    </div>
  );
}
EOF
