  await p.screenshot({path:`${out}/chip-tooltip-hover-terraria-${tag}.png`});
  await backups.click(); await p.waitForTimeout(500);
  await p.screenshot({path:`${out}/click-feedback-and-preloader-terraria-${tag}.png`});
