  await p.getByRole("button",{name:/^Opening Backups/}).click({force:true,timeout:500}).catch(()=>{}); // double-click guard
  await p.waitForTimeout(3000);
  console.log(tag,"path bar after:", (await p.getByTestId("path-bar").innerText()).replace(/\n/g," "));
  await p.screenshot({path:`${out}/after-open-backups-terraria-${tag}.png`});
  // 6 deep path bar on mobile
  await open(p,"family=terraria&deep=/opt/terraria/backups/world%20saves/2026-10-05/%C3%A9t%C3%A9&start=/opt/terraria/backups/world%20saves/2026-10-05/%C3%A9t%C3%A9");
  await p.screenshot({path:`${out}/pathbar-deep-${tag}.png`});
  // 7 missing folder: created-later fallback + inline note
