  for (const [n,q] of [["minecraft-paper","family=minecraft&variant=paper"],["valheim-bepinex","family=valheim&variant=bepinex"],["palworld","family=palworld"],["sonsoftheforest","family=sonsoftheforest"],["vps","family=vps"]]) { await open(p,q); await p.screenshot({path:`${out}/strip-${n}-${tag}.png`}); }
  // tour
  for (const [n,q] of [["minecraft-paper","family=minecraft&variant=paper&tour=1"],["minecraft-fabric","family=minecraft&variant=fabric&tour=1"],["valheim-bepinex","family=valheim&variant=bepinex&tour=1"],["terraria","family=terraria&tour=1"],["sonsoftheforest-saves-config","family=sonsoftheforest&tour=1"],["minecraft-vanilla","family=minecraft&variant=vanilla&tour=1"]]) {
    await open(p,q); await p.getByRole("button",{name:/take the tour|tour/i}).first().click(); await p.waitForTimeout(1200);
    await p.screenshot({path:`${out}/tour/step-files-guides-${n}-${tag}.png`});
    const dlg = p.locator('[role=dialog]').first();
    if (await dlg.count()) { console.log(tag,n,"TOUR:", (await dlg.innerText()).replace(/\n+/g," | ").slice(0,700)); }
    // next step (files-os)
    await p.getByRole("button",{name:/next|continue/i}).first().click().catch(()=>{}); await p.waitForTimeout(900);
    if (n==="terraria"||n==="minecraft-paper") await p.screenshot({path:`${out}/tour/step-files-os-${n}-${tag}.png`});
  }
  await ctx.close();
}
await b.close();
